/**
 * @changelog
 *   v1.0.0 - 新增引擎侧模块级阶段耗时桥接：读取 WebEngine 的各模块 update 耗时快照（1 层调用），
 *            供性能面板「阶段耗时统计」子面板展示。与 useRenderStageProfiler（pass 级 CPU/GPU）互补。
 *            REQ: 20260924-engine-stage-profiler
 * /@changelog
 *
 * @author DannyCheung
 */
import { ref, shallowRef } from 'vue';
import type { EngineContext, EngineStageProfileSnapshot } from '@tencent/viewer-sdk';

/**
 * useEngineStageProfiler — 引擎模块耗时诊断桥接
 *
 * 设计对齐 useRenderStageProfiler：
 * - 懒探测：引擎未实现该能力（mock / 旧版本）时 `available=false`，面板给出提示而非报错
 * - 只在启用时拉取快照；禁用时引擎侧主循环直通（零开销），这里也不读数据
 * - 不把引擎对象放入 Vue 响应式状态（快照里只有纯数据）
 */
export function useEngineStageProfiler(getCtx: () => EngineContext | undefined) {
  /** 当前引擎是否实现了阶段耗时接口 */
  const available = ref(false);
  /** 诊断是否启用（与引擎侧状态一致） */
  const enabled = ref(false);
  const error = ref<string | null>(null);
  const snapshot = shallowRef<EngineStageProfileSnapshot | null>(null);

  /** 拉取一次快照；返回当前是否处于启用态（供面板决定是否继续轮询）。 */
  function refresh(): boolean {
    const engine = getCtx()?.engine;
    if (!engine?.getStageProfileSnapshot || !engine?.isStageProfilerEnabled) {
      available.value = false;
      enabled.value = false;
      snapshot.value = null;
      error.value = 'EngineRegistrar 未实现阶段耗时接口（引擎版本过旧或为 mock）';
      return false;
    }
    try {
      available.value = true;
      enabled.value = engine.isStageProfilerEnabled();
      snapshot.value = enabled.value ? (engine.getStageProfileSnapshot() ?? null) : null;
      error.value = null;
      return enabled.value;
    } catch (reason) {
      available.value = false;
      enabled.value = false;
      snapshot.value = null;
      error.value = reason instanceof Error ? reason.message : String(reason);
      return false;
    }
  }

  /** 开关诊断；开启后立即取一次快照，关闭时清空本地快照。 */
  function setEnabled(nextEnabled: boolean): void {
    const engine = getCtx()?.engine;
    if (!engine?.setStageProfilerEnabled) {
      error.value = 'EngineRegistrar 未实现阶段耗时接口';
      return;
    }
    try {
      engine.setStageProfilerEnabled(nextEnabled);
      enabled.value = nextEnabled;
      snapshot.value = nextEnabled ? (engine.getStageProfileSnapshot?.() ?? null) : null;
      error.value = null;
    } catch (reason) {
      enabled.value = false;
      snapshot.value = null;
      error.value = reason instanceof Error ? reason.message : String(reason);
    }
  }

  return { available, enabled, error, snapshot, refresh, setEnabled };
}
