<template>
  <div v-show="visible" class="scene-panel">
    <div class="scene-header">
      <h3>🎬 场景面板</h3>
      <button class="close-btn" title="关闭场景面板" @click="onClose">×</button>
    </div>

    <div class="scene-content">
      <section class="scene-subpanel">
        <h4>🐞 调试</h4>
        <SceneDebugSubpanel
          ref="debugSubpanelRef"
          :initial-config="initialConfig"
          @config-change="onConfigChange"
          @module-toggle="onModuleToggle"
        />
      </section>
      <section class="scene-subpanel">
        <h4>🧊 物理</h4>
        <ScenePhysicsSubpanel
          @config-change="emit('configChange', $event)"
          @reset-physics="emit('resetPhysics')"
        />
      </section>
      <section class="scene-subpanel navigation-subpanel">
        <h4>🧭 导航</h4>
        <div class="placeholder">功能迁移中…</div>
      </section>
      <section class="scene-subpanel">
        <h4>📦 实体</h4>
        <SceneEntitySubpanel />
      </section>
    </div>
  </div>
</template>

<script setup lang="ts">
/**
 * @changelog
 *   v2.0.0 - 接入三类场景子面板，统一对外暴露高斯区域模块和可视化同步接口。
 *            REQ: debugpanel-拆分-阶段2 TECH: scene-panel-subpanel-migration
 * /@changelog
 *
 * @author DannyCheung
 */
import { ref } from 'vue';
import type { DebugConfig } from '@tencent/viewer-sdk';
import SceneDebugSubpanel from './SceneDebugSubpanel.vue';
import SceneEntitySubpanel from './SceneEntitySubpanel.vue';
import ScenePhysicsSubpanel from './ScenePhysicsSubpanel.vue';

interface Props {
  visible?: boolean;
  initialConfig?: Partial<DebugConfig>;
}

withDefaults(defineProps<Props>(), { visible: false, initialConfig: undefined });
const emit = defineEmits<{
  close: [];
  'update:visible': [value: boolean];
  configChange: [config: unknown];
  resetPhysics: [];
  moduleToggle: [moduleName: string, shouldLoad: boolean];
}>();

const debugSubpanelRef = ref<InstanceType<typeof SceneDebugSubpanel> | null>(null);

function onClose(): void {
  emit('close');
  emit('update:visible', false);
}

function onConfigChange(config: unknown): void {
  emit('configChange', config);
}

function onModuleToggle(moduleName: string, shouldLoad: boolean): void {
  emit('moduleToggle', moduleName, shouldLoad);
}

function applyDebugConfig(partial: Partial<DebugConfig>): void {
  debugSubpanelRef.value?.applyConfig(partial);
}

function setRegionModules(modules: Array<{ id?: string; name: string }>): void {
  debugSubpanelRef.value?.setRegionModules(modules);
}

function onModuleLoaded(moduleName: string): void {
  debugSubpanelRef.value?.onModuleLoaded(moduleName);
}

function onModuleLoadFailed(moduleName: string): void {
  debugSubpanelRef.value?.onModuleLoadFailed(moduleName);
}

function onModuleUnloaded(moduleName: string): void {
  debugSubpanelRef.value?.onModuleUnloaded(moduleName);
}

function getLoadingModules(): string[] {
  return debugSubpanelRef.value?.getLoadingModules() ?? [];
}

defineExpose({
  applyDebugConfig,
  getLoadingModules,
  onModuleLoaded,
  onModuleLoadFailed,
  onModuleUnloaded,
  setRegionModules,
});
</script>

