import { onMounted, onUnmounted, ref } from 'vue';
import type { EngineContext, AudioDebugTrackSnapshot, AudioDebugZoneSnapshot } from '@tencent/viewer-sdk';
import { audioModule } from '@tencent/viewer-sdk';

const POLL_INTERVAL_MS = 200;

const bgmMasterVolume = ref(100);
const sfxMasterVolume = ref(100);
const muted = ref(false);
const audioCtxState = ref<'running' | 'suspended' | 'closed' | 'interrupted' | 'unknown'>('unknown');
const tracks = ref<AudioDebugTrackSnapshot[]>([]);
const zones = ref<AudioDebugZoneSnapshot[]>([]);
const playerInsideZones = ref<string[]>([]);

let pollTimer: ReturnType<typeof setInterval> | null = null;
let consumerCount = 0;
let activeGetCtx: (() => EngineContext | undefined) | null = null;

function clamp01(v: number): number {
  return Math.max(0, Math.min(1, v));
}

function toPercent(v: number): number {
  return Math.round(clamp01(v) * 100);
}

function readCtx(): EngineContext | undefined {
  return activeGetCtx?.();
}

function refreshSnapshot(): void {
  const ctx = readCtx();
  if (!ctx) return;

  const snapshot = audioModule.getDebugSnapshot(ctx);
  audioCtxState.value = snapshot.audioCtxState;
  muted.value = snapshot.muted;
  bgmMasterVolume.value = toPercent(snapshot.bgmMasterVolume);
  sfxMasterVolume.value = toPercent(snapshot.sfxMasterVolume);
  tracks.value = snapshot.tracks;
  zones.value = snapshot.zones;
  playerInsideZones.value = snapshot.playerInsideZones;
}

function startPolling(): void {
  if (pollTimer) return;
  pollTimer = setInterval(refreshSnapshot, POLL_INTERVAL_MS);
}

function stopPolling(): void {
  if (!pollTimer) return;
  clearInterval(pollTimer);
  pollTimer = null;
}

export function useAudioParams(getCtx: () => EngineContext | undefined) {
  activeGetCtx = getCtx;

  onMounted(() => {
    consumerCount += 1;
    startPolling();
    refreshSnapshot();
  });

  onUnmounted(() => {
    consumerCount = Math.max(0, consumerCount - 1);
    if (consumerCount === 0) {
      stopPolling();
    }
  });

  function setBgmMasterVolume(valuePercent: number): void {
    const ctx = readCtx();
    if (!ctx) return;
    audioModule.setBgmMasterVolume(ctx, clamp01(valuePercent / 100));
    refreshSnapshot();
  }

  function setSfxMasterVolume(valuePercent: number): void {
    const ctx = readCtx();
    if (!ctx) return;
    audioModule.setSfxMasterVolume(ctx, clamp01(valuePercent / 100));
    refreshSnapshot();
  }

  function setMuted(nextMuted: boolean): void {
    const ctx = readCtx();
    if (!ctx) return;
    audioModule.setMuted(ctx, nextMuted);
    refreshSnapshot();
  }

  function setTrackVolume(target: 'bgm' | 'sfx', id: string, valuePercent: number): void {
    const ctx = readCtx();
    if (!ctx) return;
    audioModule.setTrackVolume(ctx, target, id, clamp01(valuePercent / 100));
    refreshSnapshot();
  }

  function play(target: 'bgm' | 'sfx', id: string): void {
    const ctx = readCtx();
    if (!ctx) return;
    if (target === 'bgm') {
      audioModule.playBgm(ctx, id);
    } else {
      audioModule.playSfx(ctx, id);
    }
    refreshSnapshot();
  }

  function stop(target: 'bgm' | 'sfx', id?: string): void {
    const ctx = readCtx();
    if (!ctx) return;
    if (target === 'bgm') {
      audioModule.stopBgm(ctx, id);
    } else {
      audioModule.stopSfx(ctx, id);
    }
    refreshSnapshot();
  }

  async function loadAndPlayLocal(
    file: File,
    kind: '2d' | '3d',
    target: 'bgm' | 'sfx',
    opts?: {
      zoneId?: string;
    },
  ): Promise<string> {
    const ctx = readCtx();
    if (!ctx) {
      throw new Error('game context not ready');
    }
    const id = await audioModule.loadAndPlayLocal(ctx, file, kind, target, opts);
    refreshSnapshot();
    return id;
  }

  function stopLocal(id?: string): void {
    const ctx = readCtx();
    if (!ctx) return;
    audioModule.stopLocal(ctx, id);
    refreshSnapshot();
  }

  return {
    bgmMasterVolume,
    sfxMasterVolume,
    muted,
    audioCtxState,
    tracks,
    zones,
    playerInsideZones,
    refreshSnapshot,
    setBgmMasterVolume,
    setSfxMasterVolume,
    setMuted,
    setTrackVolume,
    play,
    stop,
    loadAndPlayLocal,
    stopLocal,
  };
}
