/**
 * @changelog
 *   v1.0.0 - 初始实现：封装 setGaussianVisible/getGaussianVisible 的响应式包装。
 *            DebugPanel「高斯泼溅」分组用一个复选框绑定 visible，切换时同步到 SDK。
 *            REQ: 20260727-debugpanel-gaussian-visibility
 * /@changelog
 *
 * @author v_weiqinlin
 */
import { ref } from 'vue';
import type { EngineContext } from '@tencent/viewer-sdk';
// v6.0.0：setGaussianVisible / getGaussianVisible 改走 gs3dModule.api.xxx(ctx, ...)
import { gs3dModule, getModule } from '@tencent/viewer-sdk';

/**
 * useGaussianVisibility — 高斯泼溅整体显隐开关（DebugPanel 消费）
 *
 * - `visible` reactive ref：DebugPanel checkbox 双向绑定
 * - `refresh()`：从 gs3dModule 读回当前状态（1s 轮询里调，同步外部修改）
 * - `toggle()`：checkbox @change 里调用，把 `visible.value` 应用到 SDK
 */
export function useGaussianVisibility(getCtx: () => EngineContext | undefined) {
  const visible = ref(true);

  function refresh(): void {
    const ctx = getCtx();
    if (!ctx) return;
    try {
      visible.value = getModule(ctx, gs3dModule).api.getGaussianVisible(ctx);
    } catch {
      /* gs3dModule 未就绪，忽略 */
    }
  }

  function toggle(): void {
    const ctx = getCtx();
    if (!ctx) return;
    try {
      getModule(ctx, gs3dModule).api.setGaussianVisible(ctx, visible.value);
    } catch (err) {
      console.warn('⚠️ 切换高斯显隐失败（gs3dModule 未就绪）:', err);
    }
  }

  return { visible, refresh, toggle };
}
