import * as THREE from 'three';
import { ref } from 'vue';
import type { EngineContext, LightMeshState, LightState } from '@tencent/viewer-sdk';
import { lightMeshModule, lightModule, getModule } from '@tencent/viewer-sdk';

export interface LightMeshGroupPanelInfo {
  name: string;
  url: string;
  lightsCount: number;
  visible: boolean;
}

const LIGHT_MESH_MARKER_GROUP_NAME = 'DebugLightMeshLightMarkers';
const DEFAULT_LIGHT_MARKER_RADIUS = 0.12;
const MIN_POINT_LIGHT_RADIUS = 0.2;

/**
 * useLightMeshParams — lightMesh 组 DebugPanel 状态 + 命令式 action 封装。
 *
 * 设计遵循 useHdriParams 范式：
 * - `getCtx()` 工厂返回 `EngineContext | undefined`
 * - 所有 action 内置 try/catch 探测 `lightMeshModule` 是否注册
 * - `refreshSnapshot` 按轮询读取所有组的快照信息
 */
export function useLightMeshParams(getCtx: () => EngineContext | undefined) {
  /** 模块是否已注册 */
  const meshRegistered = ref(false);

  /** 已加载的 lightMesh 组列表 */
  const meshGroups = ref<LightMeshGroupPanelInfo[]>([]);

  /** 光源总数 */
  const totalLights = ref(0);

  /** 是否显示 lightMesh 灯光位置球 */
  const showLightMarkers = ref(false);

  /** 当前场景中标记球数量 */
  const markerCount = ref(0);

  /** 标记球根组（挂在 LightState.lightGroup 下） */
  let markerGroup: THREE.Group | null = null;

  const worldPos = new THREE.Vector3();

  function disposeMarkerChildren(): void {
    if (!markerGroup) return;

    for (const child of markerGroup.children) {
      const mesh = child as THREE.Mesh;
      mesh.geometry?.dispose?.();
      if (Array.isArray(mesh.material)) {
        mesh.material.forEach((m) => m.dispose());
      } else {
        mesh.material?.dispose?.();
      }
    }
    markerGroup.clear();
    markerCount.value = 0;
  }

  function removeMarkerGroup(): void {
    if (!markerGroup) return;
    disposeMarkerChildren();
    markerGroup.parent?.remove(markerGroup);
    markerGroup = null;
  }

  function ensureMarkerGroup(lightGroup: THREE.Group): THREE.Group {
    if (markerGroup?.parent === lightGroup) return markerGroup;

    removeMarkerGroup();

    const group = new THREE.Group();
    group.name = LIGHT_MESH_MARKER_GROUP_NAME;
    lightGroup.add(group);
    markerGroup = group;
    return group;
  }

  function resolveMarkerRadius(light: THREE.Light): number {
    const point = light as THREE.PointLight;
    if (point.isPointLight) {
      // 按用户诉求：PointLight 小球大小 = 灯光影响范围（distance）
      // distance<=0 代表无限范围，调试球使用最小半径兜底避免吞屏。
      return point.distance > 0 ? point.distance : MIN_POINT_LIGHT_RADIUS;
    }
    return DEFAULT_LIGHT_MARKER_RADIUS;
  }

  function createLightMarker(light: THREE.Light, lightGroup: THREE.Group): THREE.Mesh {
    const radius = Math.max(resolveMarkerRadius(light), 0.01);
    const geometry = new THREE.SphereGeometry(radius, 12, 8);
    const material = new THREE.MeshBasicMaterial({
      color: light.color?.getHex?.() ?? 0xffffff,
      transparent: true,
      opacity: 0.25,
      depthTest: false,
    });

    const marker = new THREE.Mesh(geometry, material);

    // 取世界坐标，再转换到 lightGroup 局部坐标，兼容父级层级变换
    light.getWorldPosition(worldPos);
    lightGroup.worldToLocal(worldPos);
    marker.position.copy(worldPos);

    marker.name = `LightMeshMarker:${light.name || '(unnamed)'}`;
    marker.renderOrder = 999;
    return marker;
  }

  function syncLightMarkers(): void {
    const ctx = getCtx();
    if (!ctx || !showLightMarkers.value) return;

    try {
      const lightMeshState = getModule<LightMeshState>(ctx, lightMeshModule);
      const { lightGroup } = getModule<LightState>(ctx, lightModule);

      const group = ensureMarkerGroup(lightGroup);
      disposeMarkerChildren();

      let count = 0;
      for (const item of lightMeshState.groups.values()) {
        for (const light of item.lights) {
          group.add(createLightMarker(light, lightGroup));
          count++;
        }
      }
      markerCount.value = count;
    } catch {
      // 模块未注册/上下文失效时静默忽略
      removeMarkerGroup();
    }
  }

  /**
   * 从 lightMeshModule 读取所有组的当前快照。
   * 模块未注册时静默跳过，`meshRegistered` 置 false。
   */
  function refreshSnapshot(): void {
    const ctx = getCtx();
    if (!ctx) return;

    try {
      const state = getModule<LightMeshState>(ctx, lightMeshModule);
      meshRegistered.value = true;

      const groupsSnapshot: LightMeshGroupPanelInfo[] = [];
      let lights = 0;
      for (const item of state.groups.values()) {
        groupsSnapshot.push({
          name: item.name,
          url: item.url,
          lightsCount: item.lights.length,
          visible: item.root.visible,
        });
        lights += item.lights.length;
      }
      meshGroups.value = groupsSnapshot;
      totalLights.value = lights;

      if (showLightMarkers.value) {
        syncLightMarkers();
      }
    } catch {
      meshRegistered.value = false;
      meshGroups.value = [];
      totalLights.value = 0;
      markerCount.value = 0;
      removeMarkerGroup();
    }
  }

  /** 整组显隐开关 */
  function setGroupVisible(name: string, visible: boolean): void {
    const ctx = getCtx();
    if (!ctx) return;
    try {
      lightMeshModule.setGroupVisible(ctx, name, visible);
    } catch {
      /* 未注册，忽略 */
    }
  }

  /** 移除指定组 */
  function removeGroup(name: string): void {
    const ctx = getCtx();
    if (!ctx) return;
    try {
      lightMeshModule.removeGroup(ctx, name);
      refreshSnapshot();
    } catch {
      /* 未注册，忽略 */
    }
  }

  /** 切换是否显示 lightMesh 灯光位置球 */
  function setLightMarkersEnabled(enabled: boolean): void {
    showLightMarkers.value = enabled;
    if (!enabled) {
      removeMarkerGroup();
      return;
    }
    syncLightMarkers();
  }

  /** 组件卸载时显式清理几何/材质与场景节点 */
  function disposeLightMarkers(): void {
    removeMarkerGroup();
  }

  return {
    meshRegistered,
    meshGroups,
    totalLights,
    showLightMarkers,
    markerCount,
    refreshSnapshot,
    setGroupVisible,
    removeGroup,
    setLightMarkersEnabled,
    disposeLightMarkers,
  };
}
