/**
 * @changelog
 *   v1.0.0 - 抽离自 DebugPanel.vue HDRI 控制块（行 1036-1486）；封装 hdriModule.xxx(ctx, ...) 实例 API
 *            的快照读取 + 命令式 setter，DebugPanel 仅 import 本 composable 即可，不再直接依赖
 *            viewer-sdk 的 HdriModule 类（C3：去 static 改造后期建议外部走单例）。
 *            REQ: viewer-sdk-light-static-to-instance
 *   v1.1.0 - 追加 HDRI Debug/Export 族 7 个 action（showDebugTorus/hideDebugTorus/showSpheres/
 *            hideSpheres/downloadPanorama/downloadSixFaces/downloadCurrentEnvMap），对应
 *            HdriModule v2.8.0 收编入 class 的 7 个实例方法。DebugPanel.vue 5 个 handler 从
 *            `props.sceneManager.xxx()` 迁移到本 composable action（对齐 v1.0.0 既定 composable
 *            范式），SceneManager v14.4.0 同步删除对应转发壳。所有 action 保持 try/catch 探测
 *            hdriModule 未注册（静默跳过，与既有 setter 一致）。
 *            REQ: 20260722-hdri-debug-export-sink-into-module
 *   v1.2.0 - showDebugTorus/hideDebugTorus/showSpheres/hideSpheres 4 个 debug mesh action 改调
 *            debugModule（自 hdri-module v2.9.0 迁出）。debug mesh 是「基础模型 + 光照验证」，
 *            与 HDR 是否加载无关；原走 hdriModule 时若场景未配 lighting.hdri 则 hdriModule 未注册，
 *            assertModuleRegistered 抛错被 try/catch 静默吞掉，导致「能勾选但 mesh 不创建」。
 *            debugModule 由 H5 层 extraModules 始终装配，迁后与 HDR 配置解耦。
 *            BUGFIX: debug-mesh-indep-of-hdri
 * /@changelog
 *
 * @author fancylin
 */
import { reactive, ref } from 'vue';
import type { EngineContext } from '@tencent/viewer-sdk';
// v1.2.0：Debug mesh 可视化迁到 debugModule（与 HDR 配置解耦）；hdriModule 保留用于 HDRI 贴图加载/参数。
import { hdriModule, debugModule } from '@tencent/viewer-sdk';

export interface HdriPanelParams {
  intensity: number;
  background: boolean;
  backgroundBlurriness: number;
  backgroundIntensity: number;
  exposure: number;
}

/**
 * useHdriParams — HDRI 面板状态 + 命令式 action 封装
 *
 * 设计要点：
 * - `getCtx()` 工厂返回 `EngineContext | undefined`：sceneManager 可能尚未初始化
 * - 所有 action 都内置 try/catch 探测 `hdriModule` 是否注册（D-6：lighting.hdri 字段缺失即未注册）
 * - 不做 `watch(params, ...)` 自动同步：DebugPanel 走 `@change` 命令式回调，避免双向同步引入隐式行为
 * - `refreshFromConfig` 读取 hdriModule 当前快照写入 reactive params；调用时机由 DebugPanel onMounted/loadScene 决定
 */
export function useHdriParams(getCtx: () => EngineContext | undefined) {
  /** 面板参数（与原 DebugPanel hdriParams 同结构） */
  const hdriParams = reactive<HdriPanelParams>({
    intensity: 1.0,
    background: true,
    backgroundBlurriness: 0,
    backgroundIntensity: 1.0,
    exposure: 1.0,
  });

  /** HDR 是否已加载（从配置/Debug 上传） */
  const isHDRLoaded = ref(false);
  /** 是否来自配置（vs Debug 上传） */
  const isConfigHDR = ref(false);
  /** 当前 HDR 文件名（展示用） */
  const hdrFileName = ref('');
  /** 当前 HDR 文件 URL（blob 或配置 URL） */
  const hdrFileUrl = ref('');

  /**
   * 从 hdriModule 当前 state 同步面板参数 + 加载状态。
   * 若 hdriModule 未注册（lighting.hdri 字段缺失），静默跳过。
   *
   * @param exposureGetter 可选 — toneMapping exposure 由 sceneManager 提供，独立于 hdriModule
   * @returns 是否同步成功（用于调用方决定是否输出日志）
   */
  function refreshFromConfig(exposureGetter?: () => number): boolean {
    const ctx = getCtx();
    if (!ctx) return false;

    let hdriConfig;
    try {
      hdriConfig = hdriModule.getHDRIConfig(ctx);
    } catch {
      // hdriModule 未注册
      return false;
    }

    const exposure = exposureGetter?.() ?? hdriParams.exposure;

    if (hdriConfig?.url) {
      hdrFileName.value = hdriConfig.url.split('/').pop() || 'config-hdri';
      hdrFileUrl.value = hdriConfig.url;
      isHDRLoaded.value = hdriModule.hasHDRIEnvironment(ctx);
      isConfigHDR.value = true;

      hdriParams.intensity = hdriModule.getEnvironmentIntensity(ctx);
      hdriParams.background = hdriModule.isHDRIBackgroundEnabled(ctx);
      hdriParams.backgroundBlurriness = hdriModule.getBackgroundBlurriness(ctx);
      hdriParams.backgroundIntensity = hdriModule.getBackgroundIntensity(ctx);
      hdriParams.exposure = exposure;
      return true;
    }

    if (hdriModule.hasHDRIEnvironment(ctx)) {
      isHDRLoaded.value = true;
      isConfigHDR.value = false;
      hdriParams.intensity = hdriModule.getEnvironmentIntensity(ctx);
      hdriParams.background = hdriModule.isHDRIBackgroundEnabled(ctx);
      hdriParams.backgroundBlurriness = hdriModule.getBackgroundBlurriness(ctx);
      hdriParams.backgroundIntensity = hdriModule.getBackgroundIntensity(ctx);
      hdriParams.exposure = exposure;
      return true;
    }

    return false;
  }

  /**
   * 加载 Debug HDR（用户从面板上传的 .hdr / .hdr.jpg / .png / .jpg）
   * @returns 加载成功 → true；hdriModule 未注册或失败 → false
   */
  async function loadDebugHDR(url: string, fileName: string): Promise<boolean> {
    const ctx = getCtx();
    if (!ctx) return false;
    try {
      await hdriModule.loadDebugUltraHDR(ctx, url, fileName);
      isHDRLoaded.value = true;
      return true;
    } catch (err) {
      console.warn('⚠️ hdriModule 未注册（场景无 lighting.hdri 配置），无法加载 HDR 环境:', err);
      return false;
    }
  }

  /**
   * 卸载 Debug HDR，并把面板参数重置为默认值。
   */
  function removeDebugHDR(): boolean {
    const ctx = getCtx();
    if (!ctx) return false;
    try {
      hdriModule.removeDebugUltraHDR(ctx);
      isHDRLoaded.value = false;
      hdriParams.intensity = 1.0;
      hdriParams.background = true;
      hdriParams.backgroundBlurriness = 0;
      hdriParams.backgroundIntensity = 1.0;
      hdriParams.exposure = 1.0;
      return true;
    } catch (err) {
      console.warn('⚠️ hdriModule 未注册，无法卸载 HDR 环境:', err);
      return false;
    }
  }

  // ======================== 单参数 setter（@change 回调） ========================

  function applyIntensity(): void {
    const ctx = getCtx();
    if (!ctx) return;
    try {
      hdriModule.setEnvironmentIntensity(ctx, hdriParams.intensity);
    } catch {
      /* hdriModule 未注册，忽略 */
    }
  }

  function applyBackground(): void {
    const ctx = getCtx();
    if (!ctx) return;
    try {
      hdriModule.setHDRIBackground(ctx, hdriParams.background);
    } catch {
      /* hdriModule 未注册，忽略 */
    }
  }

  function applyBlurriness(): void {
    const ctx = getCtx();
    if (!ctx) return;
    try {
      hdriModule.setBackgroundBlurriness(ctx, hdriParams.backgroundBlurriness);
    } catch {
      /* hdriModule 未注册，忽略 */
    }
  }

  function applyBackgroundIntensity(): void {
    const ctx = getCtx();
    if (!ctx) return;
    try {
      hdriModule.setBackgroundIntensity(ctx, hdriParams.backgroundIntensity);
    } catch {
      /* hdriModule 未注册，忽略 */
    }
  }

  // ======================== Debug 可视化 action（v1.1.0） ========================

  /** 显示 Debug HDR 立方体网格（金属反射球，用于可视化 IBL，与 HDR 配置无关） */
  function showDebugTorus(): void {
    const ctx = getCtx();
    if (!ctx) return;
    try {
      debugModule.showDebugTorusMesh(ctx);
    } catch {
      /* debugModule 未装配，忽略 */
    }
  }

  /** 隐藏 Debug HDR 立方体网格 */
  function hideDebugTorus(): void {
    const ctx = getCtx();
    if (!ctx) return;
    try {
      debugModule.hideDebugTorusMesh(ctx);
    } catch {
      /* debugModule 未装配，忽略 */
    }
  }

  /** 显示 Debug 球体（灰球 RGB128 + 白球 RGB255，用于光照强度校准） */
  function showSpheres(): void {
    const ctx = getCtx();
    if (!ctx) return;
    try {
      debugModule.showDebugSpheres(ctx);
    } catch {
      /* debugModule 未装配，忽略 */
    }
  }

  /** 隐藏 Debug 球体 */
  function hideSpheres(): void {
    const ctx = getCtx();
    if (!ctx) return;
    try {
      debugModule.hideDebugSpheres(ctx);
    } catch {
      /* debugModule 未装配，忽略 */
    }
  }

  // ======================== HDRI 导出 action（v1.1.0） ========================

  /**
   * 下载当前场景 HDRI 全景图（经纬图 JPG）。
   * @returns 成功 → true；hdriModule 未注册 / SparkRenderer 未就绪 / 导出失败 → false
   */
  async function downloadPanorama(): Promise<boolean> {
    const ctx = getCtx();
    if (!ctx) return false;
    try {
      return await hdriModule.downloadHdriPanoramaJPG(ctx);
    } catch {
      /* hdriModule 未注册，忽略 */
      return false;
    }
  }

  /**
   * 下载当前场景 HDRI 六面图（6 张 JPG）。
   * @returns 成功 → true；hdriModule 未注册 / SparkRenderer 未就绪 / 导出失败 → false
   */
  async function downloadSixFaces(): Promise<boolean> {
    const ctx = getCtx();
    if (!ctx) return false;
    try {
      return await hdriModule.downloadHdriSixFacesJPG(ctx);
    } catch {
      /* hdriModule 未注册，忽略 */
      return false;
    }
  }

  /**
   * 下载当前 `scene.environment` 使用的纹理（直出，不重新烘焙）。
   * @returns 成功 → true；hdriModule 未注册 / environment 未设置 / 导出失败 → false
   */
  async function downloadCurrentEnvMap(): Promise<boolean> {
    const ctx = getCtx();
    if (!ctx) return false;
    try {
      return await hdriModule.downloadCurrentEnvMapJPG(ctx);
    } catch {
      /* hdriModule 未注册，忽略 */
      return false;
    }
  }

  return {
    // state
    hdriParams,
    isHDRLoaded,
    isConfigHDR,
    hdrFileName,
    hdrFileUrl,
    // actions
    refreshFromConfig,
    loadDebugHDR,
    removeDebugHDR,
    applyIntensity,
    applyBackground,
    applyBlurriness,
    applyBackgroundIntensity,
    // v1.1.0：Debug 可视化 + 导出
    showDebugTorus,
    hideDebugTorus,
    showSpheres,
    hideSpheres,
    downloadPanorama,
    downloadSixFaces,
    downloadCurrentEnvMap,
  };
}
