.debug-header { display: flex; align-items: center; justify-content: space-between; padding: 12px 16px; background: rgba(255, 255, 255, 0.05); border-bottom: 1px solid rgba(255, 255, 255, 0.1); }.debug-header h3 { margin: 0; font-size: 14px; }.close-btn { width: 24px; height: 24px; padding: 0; color: #fff; font-size: 18px; cursor: pointer; background: none; border: none; border-radius: 4px; }.close-btn:hover { background: rgba(255, 255, 255, 0.1); }
.debug-content { padding: 16px; }.debug-section { display: flex; flex-direction: column; gap: 8px; margin-bottom: 20px; }.debug-section h4 { margin: 0 0 4px; padding-bottom: 4px; color: #4caf50; font-size: 13px; border-bottom: 1px solid rgba(76, 175, 80, 0.3); }.panel-toggle-group, .debug-checkbox { display: flex; flex-direction: column; gap: 8px; }.debug-checkbox { flex-direction: row; align-items: center; cursor: pointer; }.panel-toggle-btn, .debug-button { padding: 7px 10px; color: #e0e0e0; font: inherit; font-size: 11px; cursor: pointer; background: rgba(255, 255, 255, 0.06); border: 1px solid rgba(255, 255, 255, 0.2); border-radius: 4px; }.panel-toggle-btn.active { color: #4caf50; background: rgba(76, 175, 80, 0.15); border-color: rgba(76, 175, 80, 0.6); }.debug-button:hover, .panel-toggle-btn:hover { background: rgba(255, 255, 255, 0.15); }
.info-item { display: flex; align-items: center; justify-content: space-between; padding: 6px 8px; background: rgba(255, 255, 255, 0.05); border-radius: 4px; }.slider-label { display: flex; flex-direction: column; gap: 5px; }.slider-label input { width: 100%; }.schedule-card { display: grid; grid-template-columns: 1fr auto; gap: 4px 8px; padding: 7px; background: rgba(0, 0, 0, 0.25); border-left: 2px solid #ffc107; border-radius: 4px; }.schedule-card small { grid-column: 1 / -1; color: #aaa; }.camera-sensitivity-info { display: flex; flex-direction: column; gap: 4px; padding: 8px 10px; background: rgba(0, 255, 136, 0.1); border: 1px solid rgba(0, 255, 136, 0.3); border-radius: 6px; }.camera-sensitivity-info strong { color: #00ff88; }.camera-sensitivity-info small { color: rgba(0, 255, 136, 0.7); }.debug-toggle-btn { position: fixed; top: 60px; left: 20px; display: grid; width: 40px; height: 40px; padding: 0; color: #fff; cursor: pointer; background: rgba(0, 0, 0, 0.8); border: 1px solid rgba(255, 255, 255, 0.2); border-radius: 50%; z-index: 9999; place-items: center; }.debug-toggle-icon { width: 20px; height: 20px; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; }
@media (max-width: 768px) { .debug-panel { width: calc(100vw - 40px); max-width: 320px; }.debug-toggle-btn { top: 15px; left: 15px; } }
@media (max-width: 768px) and (orientation: portrait) { .debug-toggle-btn { top: 80px; } }
</style>
