<template>
  <div v-show="visible" class="environment-panel">
    <div class="env-header">
      <h3>🌍 环境面板</h3>
      <button class="close-btn" title="关闭环境面板" @click="onClose">×</button>
    </div>

    <div class="env-content">
      <!-- 调试 -->
      <section class="env-subpanel">
        <h4>🐞 调试</h4>
        <div class="env-subpanel-body">
          <div class="checkbox-group">
            <label class="debug-checkbox">
              <input v-model="showDebugHDRMesh" type="checkbox" @change="onDebugHDRMeshChange" />
              <span>显示DebugHDR Mesh</span>
            </label>
            <label class="debug-checkbox">
              <input v-model="showDebugSpheres" type="checkbox" @change="onDebugSpheresChange" />
              <span>显示DebugMesh（灰球+白球）</span>
            </label>
            <div v-if="!postProcessingAvailable" class="subpanel-warning">
              当前场景未启用 PostProcessing（缺少 <code>renderer.postProcessing</code> 配置），深度检查器不可用。
            </div>
            <div class="depth-debug-controls" :class="{ 'subpanel-disabled': !postProcessingAvailable }">
              <label class="debug-checkbox">
                <input
                  v-model="postProcessingParams.depthDebug.source"
                  type="radio"
                  value="preDepth"
                  @change="onDepthDebugChange"
                />
                <span>PreDepthPass 深度调试（SplatDepth + coverage，RenderPass 前；无信号时显示提示）</span>
              </label>
              <label class="debug-checkbox">
                <input
                  v-model="postProcessingParams.depthDebug.source"
                  type="radio"
                  value="renderPassDepth"
                  :disabled="hybridPassActive"
                  @change="onDepthDebugChange"
                />
                <span>RenderPass 深度调试（RenderPass 后、后处理前）</span>
              </label>
              <label class="debug-checkbox">
                <input
                  v-model="postProcessingParams.depthDebug.source"
                  type="radio"
                  value="hybridPassDepth"
                  :disabled="!hybridPassActive"
                  @change="onDepthDebugChange"
                />
                <span>HybridPass 合成深度调试（Mesh Resolve + Gaussian，后处理前；未启用时不可选）</span>
              </label>
              <label class="debug-checkbox">
                <input
                  v-model="postProcessingParams.depthDebug.source"
                  type="radio"
                  value="none"
                  @change="onDepthDebugChange"
                />
                <span>关闭深度调试</span>
              </label>
              <label v-if="postProcessingParams.depthDebug.source !== 'none'" class="select-label">
                <span>深度查看模式</span>
                <select v-model="postProcessingParams.depthDebug.mode" @change="onDepthDebugChange">
                  <option value="pip">画中画（PIP）</option>
                  <option value="fullscreen">全屏</option>
                </select>
              </label>
            </div>

            <div class="depth-debug-controls" :class="{ 'subpanel-disabled': !postProcessingAvailable }">
              <label class="debug-checkbox">
                <input
                  v-model="postProcessingParams.routePreDepthToRenderPass"
                  type="checkbox"
                  @change="onRoutePreDepthToRenderPassChange"
                />
                <span>将 PreDepth 合并至主深度（包含 Gaussian；兼容 Hybrid / RenderPass）</span>
              </label>
            </div>

            <!-- 高斯深度与剔除（spark2.0 官方能力）：档位调整 + 双 pass 剔除开关 -->
            <div class="depth-debug-controls" :class="{ 'subpanel-disabled': !postProcessingAvailable }">
              <label class="select-label">
                <span>高斯深度档位</span>
                <select v-model="postProcessingParams.cull.splatDepthPreset" @change="onSplatDepthPresetChange">
                  <option value="low">低（0.05× 分辨率，最省）</option>
                  <option value="medium">中（0.1× 分辨率）</option>
                  <option value="high">高（0.5× 分辨率，最准）</option>
                </select>
              </label>
              <label class="select-label">
                <span>深度剔除档位</span>
                <select v-model="postProcessingParams.cull.occlusionPreset" @change="onOcclusionCullChange">
                  <option value="conservative">保守（轮廓最安全）</option>
                  <option value="balanced">均衡</option>
                  <option value="aggressive">激进（剔得最多）</option>
                </select>
              </label>
              <label class="debug-checkbox">
                <input
                  v-model="postProcessingParams.cull.occlusionEnabled"
                  type="checkbox"
                  @change="onOcclusionCullChange"
                />
                <span>深度剔除（按深度图剔除被遮挡的高斯）</span>
              </label>
              <label class="debug-checkbox">
                <input
                  v-model="postProcessingParams.cull.depthViewCullEnabled"
                  type="checkbox"
                  @change="onDepthViewCullChange"
                />
                <span>深度 pass 相机剔除（视锥外 / 相机后方）</span>
              </label>
              <label class="debug-checkbox">
                <input
                  v-model="postProcessingParams.cull.depthViewCullSettle"
                  type="checkbox"
                  @change="onDepthViewCullChange"
                />
                <span>深度 pass 静止保护（停稳才剔除，拖动时不剔）</span>
              </label>
              <label class="debug-checkbox">
                <input
                  v-model="postProcessingParams.cull.colorViewCullEnabled"
                  type="checkbox"
                  @change="onColorViewCullChange"
                />
                <span>彩色 pass 相机剔除（高斯 RGB 渲染，视锥外 / 相机后方）</span>
              </label>
              <label class="debug-checkbox">
                <input
                  v-model="postProcessingParams.cull.colorViewCullSettle"
                  type="checkbox"
                  @change="onColorViewCullChange"
                />
                <span>彩色 pass 静止保护（停稳才剔除，拖动时不剔）</span>
              </label>
              <!-- 诊断读数：每 1s 轮询；提交数 = 剔除后实际派发的高斯实例数，分母为网格全量 splat 数 -->
              <div class="depth-probe-hint">{{ cullReadout }}</div>
            </div>

            <div class="depth-probe-controls" :class="{ 'subpanel-disabled': !postProcessingAvailable }">
              <button class="debug-button" :disabled="depthProbePending" @click="onRequestDepthProbe">
                {{ depthProbePending ? '深度采样中...' : depthProbeArmed ? '请点击场景中的目标像素' : '采样同一像素三阶段深度' }}
              </button>
              <div v-if="depthProbeArmed" class="depth-probe-hint">请点击渲染画布；结果会读取同一 WebGL 像素。</div>
              <div v-if="depthProbeError" class="subpanel-warning">{{ depthProbeError }}</div>
              <div v-if="depthProbe" class="depth-probe-result">
                <div>UV（左下原点）：{{ formatDepthProbeNumber(depthProbe.uv.u) }}, {{ formatDepthProbeNumber(depthProbe.uv.v) }}</div>
                <div>{{ formatDepthProbeSample('SplatDepth', depthProbe.splatDepth) }}</div>
                <div>{{ formatDepthProbeSample('注入后 composer input', depthProbe.composerInputAfterPreDepth) }}</div>
                <div>{{ formatDepthProbeSample(hybridPassActive ? 'HybridPass stable（Mesh + Gaussian）' : 'RenderPass stable', depthProbe.renderPassStableDepth) }}</div>
              </div>
            </div>
          </div>

          <div class="button-group">
            <button class="debug-button" title="打印当前场景全部光源与 IBL 强度" @click="onDumpLights">
              💡 Dump Lights
            </button>
          </div>
        </div>
      </section>

      <!-- 环境：整合 时间系统(TOD) + 天空 + 云参数 -->
      <section class="env-subpanel env-env-subpanel">
        <h4>🌿 环境</h4>
        <div class="env-subpanel-body">
          <!-- 🕑 时间系统 (TOD) —— 常显；非 TOD 场景（todEnabled=false）给出橙色提示 -->
          <div class="env-block">
            <div class="env-block-header">🕑 时间系统 (TOD)</div>
            <div v-if="!todEnabled" class="subpanel-warning">
              当前场景未启用 TOD 时间系统（缺少 lighting.tod 配置），
              时间/流速调节、播放/暂停、大气参数快照均不可用。
            </div>
            <div class="tod-control" :class="{ 'subpanel-disabled': !todEnabled }">
              <!-- 手动调时间 -->
              <div class="slider-group">
                <label class="slider-label">时间: {{ todState.hour.toFixed(2) }} 时（{{ todState.phase }}）</label>
                <input
                  v-model.number="todState.hour"
                  type="range"
                  min="0"
                  max="24"
                  step="0.1"
                  class="debug-slider"
                  @input="onTodTimeChange"
                />
              </div>

              <!-- 手动调速度 -->
              <div class="slider-group">
                <label class="slider-label">流速: ×{{ todState.speed }}（86400/N 秒走完一天）</label>
                <input
                  v-model.number="todState.speed"
                  type="range"
                  min="0"
                  max="3600"
                  step="10"
                  class="debug-slider"
                  @input="onTodSpeedChange"
                />
              </div>

              <!-- 播放 / 暂停 -->
              <div class="tod-playback-buttons">
                <button class="debug-btn" :class="{ active: todState.playback === 'playing' }" @click="onTodPlay">
                  ▶ 播放
                </button>
                <button class="debug-btn" :class="{ active: todState.playback === 'paused' }" @click="onTodPause">
                  ⏸ 暂停
                </button>
              </div>

              <!-- 当前阶段大气参数（只读，订阅 onTimeChanged 实时刷新） -->
              <div v-if="todSnapshot" class="tod-snapshot">
                <div class="tod-snapshot-title">当前阶段大气参数</div>
                <div class="tod-snapshot-row"><span>turbidity</span><span>{{ todSnapshot.sky.turbidity.toFixed(2) }}</span></div>
                <div class="tod-snapshot-row"><span>rayleigh</span><span>{{ todSnapshot.sky.rayleigh.toFixed(2) }}</span></div>
                <div class="tod-snapshot-row">
                  <span>mieCoefficient</span><span>{{ (todSnapshot.sky.mieCoefficient ?? 0).toFixed(4) }}</span>
                </div>
                <div class="tod-snapshot-row">
                  <span>mieDirectionalG</span><span>{{ (todSnapshot.sky.mieDirectionalG ?? 0).toFixed(2) }}</span>
                </div>
                <div class="tod-snapshot-row"><span>elevation</span><span>{{ todSnapshot.sky.elevation.toFixed(1) }}°</span></div>
                <div class="tod-snapshot-row"><span>azimuth</span><span>{{ todSnapshot.sky.azimuth.toFixed(1) }}°</span></div>
                <div class="tod-snapshot-row">
                  <span>sun</span><span>{{ todSnapshot.sun.color }} / {{ todSnapshot.sun.intensity.toFixed(2) }}</span>
                </div>
                <div class="tod-snapshot-row">
                  <span>ambient</span><span>{{ todSnapshot.ambient.color }} / {{ todSnapshot.ambient.intensity.toFixed(2) }}</span>
                </div>
                <div class="tod-snapshot-row">
                  <span>ibl (hdri)</span>
                  <span>{{ todIblIntensity === null ? '未开启' : todIblIntensity.toFixed(2) }}</span>
                </div>
              </div>
            </div>
          </div>

          <!-- 🌤️ 天空控制 -->
          <div class="env-block">
            <div class="env-block-header">🌤️ 天空</div>
            <div class="sky-control">
              <label class="debug-checkbox">
                <input v-model="skyEnabled" type="checkbox" @change="onSkyEnabledChange" />
                <span>启用天空</span>
              </label>

              <!-- 天空参数（仅当启用时显示） -->
              <div v-if="skyEnabled" class="sky-params">
                <!-- 天空预设选择 -->
                <div class="select-group">
                  <label class="select-label">天空预设:</label>
                  <select v-model="skyPreset" class="debug-select" @change="onSkyPresetChange">
                    <option value="custom">自定义</option>
                    <option value="noon">☀️ 正午 (清澈蓝天)</option>
                    <option value="sunrise">🌅 日出</option>
                    <option value="sunset">🌇 日落</option>
                    <option value="golden">🌄 黄金时刻</option>
                    <option value="overcast">☁️ 阴天</option>
                    <option value="haze">🌫️ 雾霾天</option>
                  </select>
                </div>

                <div class="slider-group">
                  <label class="slider-label">太阳高度: {{ skyParams.elevation.toFixed(1) }}°</label>
                  <input
                    v-model.number="skyParams.elevation"
                    type="range"
                    min="0"
                    max="90"
                    step="0.5"
                    class="debug-slider"
                    @input="onSkyElevationChange"
                  />
                </div>

                <div class="slider-group">
                  <label class="slider-label">太阳方位: {{ skyParams.azimuth.toFixed(1) }}°</label>
                  <input
                    v-model.number="skyParams.azimuth"
                    type="range"
                    min="-180"
                    max="180"
                    step="1"
                    class="debug-slider"
                    @input="onSkyAzimuthChange"
                  />
                </div>

                <div class="slider-group">
                  <label class="slider-label">浑浊度: {{ skyParams.turbidity.toFixed(1) }}</label>
                  <input
                    v-model.number="skyParams.turbidity"
                    type="range"
                    min="0"
                    max="20"
                    step="0.1"
                    class="debug-slider"
                    @input="onSkyTurbidityChange"
                  />
                </div>

                <div class="slider-group">
                  <label class="slider-label">瑞利散射: {{ skyParams.rayleigh.toFixed(2) }}</label>
                  <input
                    v-model.number="skyParams.rayleigh"
                    type="range"
                    min="0"
                    max="4"
                    step="0.01"
                    class="debug-slider"
                    @input="onSkyRayleighChange"
                  />
                </div>

                <div class="slider-group">
                  <label class="slider-label">米氏系数: {{ skyParams.mieCoefficient.toFixed(4) }}</label>
                  <input
                    v-model.number="skyParams.mieCoefficient"
                    type="range"
                    min="0"
                    max="0.1"
                    step="0.0001"
                    class="debug-slider"
                    @input="onSkyMieCoefficientChange"
                  />
                </div>

                <div class="slider-group">
                  <label class="slider-label">米氏方向: {{ skyParams.mieDirectionalG.toFixed(2) }}</label>
                  <input
                    v-model.number="skyParams.mieDirectionalG"
                    type="range"
                    min="0"
                    max="1"
                    step="0.01"
                    class="debug-slider"
                    @input="onSkyMieDirectionalGChange"
                  />
                </div>

                <!-- 太阳显隐（视觉圆盘 / 平行光独立可控） -->
                <label class="debug-checkbox">
                  <input v-model="skyParams.showSunDisc" type="checkbox" @change="onSkyShowSunDiscChange" />
                  <span>显示太阳圆盘</span>
                </label>
                <label class="debug-checkbox">
                  <input v-model="skyParams.sunLightVisible" type="checkbox" @change="onSkySunLightVisibleChange" />
                  <span>启用太阳平行光</span>
                </label>
              </div>
            </div>
          </div>

          <!-- ☁️ 云参数（vendored Sky 原生 fbm 云，实时生效；仅在启用天空时显示） -->
          <div v-if="skyEnabled" class="env-block">
            <div class="env-block-header">☁️ 云参数</div>
            <div class="sky-cloud-control">
              <p class="cloud-placeholder-hint">程序化 fbm 云，实时生效；云覆盖 cloudCoverage 设为 0 即关闭云层。</p>
              <div class="slider-group">
                <label class="slider-label">云尺度 cloudScale: {{ skyParams.cloudScale.toFixed(4) }}</label>
                <input
                  v-model.number="skyParams.cloudScale"
                  type="range"
                  min="0"
                  max="0.01"
                  step="0.0001"
                  class="debug-slider"
                  @input="onSkyCloudScaleChange"
                />
              </div>
              <div class="slider-group">
                <label class="slider-label">云速度 cloudSpeed: {{ skyParams.cloudSpeed.toFixed(4) }}</label>
                <input
                  v-model.number="skyParams.cloudSpeed"
                  type="range"
                  min="0"
                  max="0.01"
                  step="0.0001"
                  class="debug-slider"
                  @input="onSkyCloudSpeedChange"
                />
              </div>
              <div class="slider-group">
                <label class="slider-label">云覆盖 cloudCoverage: {{ skyParams.cloudCoverage.toFixed(2) }}</label>
                <input
                  v-model.number="skyParams.cloudCoverage"
                  type="range"
                  min="0"
                  max="1"
                  step="0.01"
                  class="debug-slider"
                  @input="onSkyCloudCoverageChange"
                />
              </div>
              <div class="slider-group">
                <label class="slider-label">云浓度 cloudDensity: {{ skyParams.cloudDensity.toFixed(2) }}</label>
                <input
                  v-model.number="skyParams.cloudDensity"
                  type="range"
                  min="0"
                  max="1"
                  step="0.01"
                  class="debug-slider"
                  @input="onSkyCloudDensityChange"
                />
              </div>
              <div class="slider-group">
                <label class="slider-label">云高度 cloudElevation: {{ skyParams.cloudElevation.toFixed(2) }}</label>
                <input
                  v-model.number="skyParams.cloudElevation"
                  type="range"
                  min="0"
                  max="1"
                  step="0.01"
                  class="debug-slider"
                  @input="onSkyCloudElevationChange"
                />
              </div>
            </div>
          </div>
        </div>
      </section>

      <!-- 光照：整合 HDR/HDRI + lightMesh 组管理 + 光照探针 -->
      <section class="env-subpanel light-subpanel">
        <h4>💡 光照</h4>
        <div class="env-subpanel-body">
          <!-- 🌅 光照及后处理（HDR/HDRI） -->
          <div class="light-block">
            <div class="light-block-header">🌅 光照及后处理</div>

            <div class="hdr-upload-control">
              <label class="input-label">HDR环境贴图:</label>

              <!-- 如果已从配置加载了 HDR，显示配置信息 -->
              <div v-if="isHDRLoaded && isConfigHDR" class="config-hdr-info">
                <span class="config-label">📋 来自配置:</span>
                <span class="config-url" :title="hdrFileUrl">{{ hdrFileName }}</span>
              </div>

              <!-- 文件上传区域 -->
              <div
                v-else
                class="hdr-upload-area"
                :class="{ 'drag-over': isDragOver, 'has-file': hdrFileName }"
                @dragover.prevent="onDragOver"
                @dragleave.prevent="onDragLeave"
                @drop.prevent="onFileDrop"
                @click="triggerFileInput"
              >
                <input
                  ref="hdrFileInput"
                  type="file"
                  accept=".hdr,.jpg,.jpeg,.png,.hdr.jpg"
                  class="hidden-file-input"
                  @change="onFileSelect"
                />
                <div v-if="!hdrFileName" class="upload-placeholder">
                  <span class="upload-icon">📁</span>
                  <span class="upload-text">点击或拖拽上传 HDR 文件</span>
                  <span class="upload-hint">支持 .hdr.jpg, .hdr, .jpg, .png</span>
                </div>
                <div v-else class="file-info">
                  <span class="file-icon">🖼️</span>
                  <span class="file-name">{{ hdrFileName }}</span>
                  <button class="clear-file-btn" @click.stop="clearHDRFile">×</button>
                </div>
              </div>

              <div v-if="!isConfigHDR" class="hdr-button-group">
                <button class="debug-button" :disabled="!hdrFileUrl" @click="onLoadHDREnvironment">加载</button>
                <button class="debug-button secondary" :disabled="!isHDRLoaded" @click="onUnloadHDREnvironment">
                  卸载
                </button>
              </div>
            </div>

            <!-- HDRI 参数控制 -->
            <div v-if="isHDRLoaded" class="hdri-params-control">
              <div class="slider-group">
                <label class="slider-label"> 环境光强度: {{ hdriParams.intensity.toFixed(2) }} </label>
                <input
                  v-model.number="hdriParams.intensity"
                  type="range"
                  min="0"
                  max="3"
                  step="0.01"
                  class="debug-slider"
                  @input="onHDRIIntensityChange"
                />
              </div>

              <div class="slider-group">
                <label class="debug-checkbox">
                  <input v-model="hdriParams.background" type="checkbox" @change="onHDRIBackgroundChange" />
                  <span>显示HDRI背景</span>
                </label>
              </div>

              <div v-if="hdriParams.background" class="slider-group">
                <label class="slider-label"> 背景模糊度: {{ hdriParams.backgroundBlurriness.toFixed(2) }} </label>
                <input
                  v-model.number="hdriParams.backgroundBlurriness"
                  type="range"
                  min="0"
                  max="1"
                  step="0.01"
                  class="debug-slider"
                  @input="onHDRIBlurrinessChange"
                />
              </div>

              <div v-if="hdriParams.background" class="slider-group">
                <label class="slider-label"> 背景强度: {{ hdriParams.backgroundIntensity.toFixed(2) }} </label>
                <input
                  v-model.number="hdriParams.backgroundIntensity"
                  type="range"
                  min="0"
                  max="3"
                  step="0.01"
                  class="debug-slider"
                  @input="onHDRIBackgroundIntensityChange"
                />
              </div>

              <div class="slider-group">
                <label class="slider-label"> 曝光度: {{ hdriParams.exposure.toFixed(2) }} </label>
                <input
                  v-model.number="hdriParams.exposure"
                  type="range"
                  min="0"
                  max="3"
                  step="0.01"
                  class="debug-slider"
                  @input="onHDRIExposureChange"
                />
              </div>
            </div>

            <div class="hdr-button-group">
              <button class="debug-button" :disabled="isDownloadingPanorama" @click="onDownloadPanoramaJPG">
                {{ isDownloadingPanorama ? '烘焙中...' : '烘焙全景图' }}
              </button>
              <button class="debug-button secondary" :disabled="isDownloadingSixFaces" @click="onDownloadSixFacesJPG">
                {{ isDownloadingSixFaces ? '烘焙中...' : '烘焙六面图' }}
              </button>
              <button
                class="debug-button secondary"
                :disabled="isDownloadingCurrentEnvMap"
                @click="onDownloadCurrentEnvMapJPG"
              >
                {{ isDownloadingCurrentEnvMap ? '下载中...' : '下载当前EnvMap' }}
              </button>
            </div>
          </div>

          <!-- 💡 lightMesh 组管理 —— 常显；未注册时给出橙色提示 -->
          <div class="light-block">
            <div class="light-block-header">💡 lightMesh 组管理</div>
            <div v-if="!meshRegistered" class="subpanel-warning">
              当前场景未启用 lightMesh（缺少 lighting.lightMesh 配置或场景未加载含光源信息的 GLB），
              组显隐/移除/灯光位置可视化不可用。
            </div>
            <div class="lightmesh-control" :class="{ 'subpanel-disabled': !meshRegistered }">
              <div class="info-item">
                <span class="info-label">已加载组:</span>
                <span class="info-value">{{ meshGroups.length }}</span>
              </div>
              <div class="info-item">
                <span class="info-label">光源总数:</span>
                <span class="info-value">{{ totalLights }}</span>
              </div>
              <label class="debug-checkbox lightmesh-marker-toggle">
                <input
                  type="checkbox"
                  :checked="showLightMarkers"
                  @change="setLightMarkersEnabled(($event.target as HTMLInputElement).checked)"
                />
