                  <label class="slider-label">强度: {{ postProcessingParams.bloom.intensity.toFixed(2) }}</label>
                  <input
                    v-model.number="postProcessingParams.bloom.intensity"
                    type="range"
                    min="0"
                    max="5"
                    step="0.01"
                    class="debug-slider"
                    @input="applyBloomIntensity"
                  />
                </div>
                <div class="slider-group">
                  <label class="slider-label">
                    亮度阈值: {{ postProcessingParams.bloom.luminanceThreshold.toFixed(2) }}
                  </label>
                  <input
                    v-model.number="postProcessingParams.bloom.luminanceThreshold"
                    type="range"
                    min="0"
                    max="1"
                    step="0.01"
                    class="debug-slider"
                    @input="applyBloomThreshold"
                  />
                </div>
                <div class="slider-group">
                  <label class="slider-label">模糊半径: {{ postProcessingParams.bloom.radius.toFixed(2) }}</label>
                  <input
                    v-model.number="postProcessingParams.bloom.radius"
                    type="range"
                    min="0"
                    max="1"
                    step="0.01"
                    class="debug-slider"
