                    @input="applyBloomSmoothing"
                  />
                </div>
                <div class="slider-group">
                  <label class="slider-label">Mipmap 层级: {{ postProcessingParams.bloom.levels }}</label>
                  <input
                    v-model.number="postProcessingParams.bloom.levels"
                    type="range"
                    min="1"
                    max="16"
                    step="1"
                    class="debug-slider"
                    @input="applyBloomLevels"
                  />
                </div>
                <div class="slider-group">
                  <label class="slider-label">
                    内部分辨率: {{ postProcessingParams.bloom.resolutionScale.toFixed(2) }}
                  </label>
                  <input
                    v-model.number="postProcessingParams.bloom.resolutionScale"
                    type="range"
                    min="0.1"
                    max="1"
                    step="0.05"
                    class="debug-slider"
                    @input="applyBloomResolutionScale"
                  />
