                    min="0"
                    max="5"
                    step="0.01"
                    class="debug-slider"
                    @input="applySsaoIntensity"
                  />
                </div>
                <div class="slider-group">
                  <label class="slider-label">采样半径: {{ postProcessingParams.ssao.radius.toFixed(4) }}</label>
                  <input
                    v-model.number="postProcessingParams.ssao.radius"
                    type="range"
                    min="0.001"
                    max="1"
                    step="0.001"
                    class="debug-slider"
                    @input="applySsaoRadius"
                  />
                </div>
                <div class="slider-group">
                  <label class="slider-label">
                    法线/AO 分辨率: {{ postProcessingParams.ssao.resolutionScale.toFixed(2) }}
                  </label>
                  <input
                    v-model.number="postProcessingParams.ssao.resolutionScale"
                    type="range"
                    min="0.25"
                    max="1"
                    step="0.05"
                    class="debug-slider"
                    @input="applySsaoResolutionScale"
                  />
                </div>
              </div>

              <!-- 屏幕空间最终可见表面阴影 -->
              <label class="debug-checkbox">
                <input
