                    <option v-for="mode in ppToneMappingModes" :key="mode" :value="mode">{{ mode }}</option>
                  </select>
                </div>
                <div class="slider-group">
                  <label class="slider-label">
                    曝光: {{ postProcessingParams.pmndrsToneMapping.exposure.toFixed(2) }}
