              </div>
            </div>
          </div>

          <!-- 🎨 ToneMapping（Three.js 原生，直调 rendererModule） -->
          <div class="post-block">
            <div class="post-block-header">🎨 ToneMapping</div>
            <div class="tonemapping-control">
              <div class="select-group">
                <label class="input-label">映射类型:</label>
                <select v-model="toneMappingType" class="debug-select" @change="onToneMappingTypeChange">
                  <option v-for="type in toneMappingTypes" :key="type" :value="type">
