                  v-model.number="toneMappingExposure"
                  type="range"
                  min="0"
                  max="5"
                  step="0.01"
                  class="debug-slider"
                  @input="onToneMappingExposureChange"
                />
              </div>
            </div>
          </div>
        </div>
      </section>
    </div>
  </div>
</template>

<script setup lang="ts">
/**
 * @changelog
 * | 版本   | 变更说明                                                                                                                                                     | 关联                                                                        |
 * | v1.0.0 | 阶段1：新建环境面板框架，横向并列 4 个占位子面板（调试/环境/光照/后处理）。                                                                                     | REQ: debugpanel-拆分-阶段1 TECH: environment-panel-phase1-framework         |
 * | v1.1.0 | 阶段2-A：从 DebugPanel 迁移 4 项调试功能到「🐞 调试」子面板——显示DebugHDR Mesh / 显示DebugMesh / SplatDepth 深度调试(PIP) / 新增 Dump Lights 按钮（globalThis.__dumpLights()）。 | REQ: debugpanel-拆分-阶段2A TECH: environment-panel-phase2-debug-migration |
 * | v1.2.0 | 阶段2-B：从 DebugPanel 迁移「🌅 光照及后处理」HDR/HDRI 上传参数区、「💡 lightMesh 组管理」、「🔆 光照探针 (Light Probe)」三大区块到「💡 光照」子面板。三区块 UI/state/handler/composable(useHdriParams/useLightMeshParams/useLightProbeParams) 集中在 EnvironmentPanel；DebugPanel 内对应段落及依赖同步移除，避免功能重复。 | REQ: debugpanel-拆分-阶段2B TECH: environment-panel-phase2-light-migration |
 * | v1.3.0 | 阶段2-C：从 DebugPanel 迁移「🕑 时间系统 (TOD)」、「🌤️ 天空」、「☁️ 云参数」三大区块到「🌿 环境」子面板。合并到统一的 refreshEnvSnapshots，含 useSkyParams / useTodParams composable 与 skyPresets 反查；DebugPanel 对应 UI/state/handler/composable 解构/生命周期调用同步移除。 | REQ: debugpanel-拆分-阶段2C TECH: environment-panel-phase2-env-migration |
 * | v1.4.0 | 阶段2-D：从 DebugPanel 迁移「🎬 后处理 (PostProcessing)」（Antialiasing/Bloom/SSAO/pmndrsToneMapping）与「🎨 ToneMapping」（Three.js 原生）两大区块到「✨ 后处理」子面板。usePostProcessingParams 解构在 EnvironmentPanel 内一次性完整拿全 apply* 方法；refreshEnvSnapshots 一并驱动后处理配置刷新与原生 ToneMapping 状态回填；DebugPanel 内对应 UI/state/handler/常量数组/init 调用同步移除。 | REQ: debugpanel-拆分-阶段2D TECH: environment-panel-phase2-post-migration |
 * | v1.4.1 | 修复：lightMesh 组管理 / 后处理 (PostProcessing) / 时间系统 (TOD) 从 `v-if` 门控改为常显——未配置场景时保持 header 可见并显示统一橙色 `.subpanel-warning` 提示，内部控件套 `.subpanel-disabled`（半透明+屏蔽点击），与既有 lightProbe 未注册提示样式统一。 | REQ: environment-panel-常显未配置提示 TECH: -                                        |
 * | v1.5.0 | 阶段1：改为 side-panel-dock 内的 flex 子项，由父级按打开顺序统一排列。 | REQ: debugpanel-拆分-阶段1 TECH: scene-panel-phase1-framework |
 * | v1.6.0 | 阶段1：调试子面板提供 PreDepth 与 RenderPass 两个深度检查器入口，并可选择画中画或全屏。 | REQ: 20260729-depth-debug TECH: depth-pipeline §4.1 |
