/**
 * 剔除诊断读数（由 refreshTimer 每 1s 刷新 cullSnapshot）。
 * 未就绪时给出明确提示，避免「面板显示可用、实际剔除没跑」的静默状态；
 * 静止保护关闭时不显示「运动中/已停稳」—— 那两项只在 settle 生效时才有意义。
 */
const cullReadout = computed(() => {
  const snap = cullSnapshot.value;
  if (!snap) return '剔除链路未就绪（等待 SplatDepthPass / SparkRenderer 创建）';
  const parts: string[] = [`深度 ${snap.depthPass.preset}`];
  const occ = snap.occlusion;
  if (occ.enabled) {
    parts.push(`深度剔除 ${occ.preset}`);
    if (occ.attachedMeshes === 0) parts.push('未挂载网格');
    if (occ.totalSplats === null) {
      // 总数取不到（网格未就绪 / 非 packed 形态）时退化为只报提交数。
      parts.push(occ.activeSplats > 0 ? `提交 ${occ.activeSplats.toLocaleString()} splat` : '提交数读取中');
    } else {
      const culledPct = occ.culledRatio === null ? '' : `（剔除 ${(occ.culledRatio * 100).toFixed(1)}%）`;
      parts.push(
        `提交 ${occ.activeSplats.toLocaleString()} / ${occ.totalSplats.toLocaleString()} splat${culledPct}`,
      );
    }
  } else {
    parts.push('深度剔除 关');
  }
  if (snap.depthPass.depthCullSettle) parts.push(`深度侧 ${snap.depthPass.depthCullSettled ? '已停稳' : '运动中'}`);
  if (snap.colorViewCull.settle) parts.push(`彩色侧 ${snap.colorViewCull.settled ? '已停稳' : '运动中'}`);
  return parts.join(' · ');
});

