/**
 * 首次 EngineContext 就绪时，触发一次快照刷新（HDRI + lightMesh + lightProbe + Sky + TOD）。
 * SDK 的 LightModule/SkyModule/TodModule 均异步注册，组件挂载时 ctx 可能尚未就绪，因此用 watch 兜底。
 */
function refreshEnvSnapshots() {
  const ctx = getCtx();
  if (!ctx) return;
  // HDRI：曝光度由 rendererModule 提供，不属于 hdriModule 内部 state
  refreshHdriFromConfig(() => rendererModule.getToneMappingExposure(ctx));
  refreshMeshSnapshot();
  // LightProbe：SDK LightModule.init 是异步注册，即使 registered=false 也尝试刷新以便就绪后自动同步
  refreshLightProbe();
  // Sky：从 skyModule 拉一次配置
  refreshSkyFromConfig();
  skyPreset.value = detectSkyPreset();
  // TOD：从 todModule 拉一次配置；若模块已注册则启动 onTimeChanged 订阅
  const todOk = refreshTodFromConfig();
  if (todOk) {
    todStartSubscription();
  }
  // 后处理面板：读取 renderer.postProcessing 配置（未配置则 available=false，UI 自动隐藏）
  refreshPostProcessingFromConfig();
  // Three.js 原生 ToneMapping：直调 rendererModule
  toneMappingType.value = rendererModule.getToneMappingType(ctx);
  toneMappingExposure.value = rendererModule.getToneMappingExposure(ctx);
}

// 定时刷新 lightMesh 快照（对齐 DebugPanel 原 1s 轮询语义，用于监听 SDK 侧组变化）
let refreshTimer: ReturnType<typeof setInterval> | null = null;

// 兜底监听 ctx 就绪（SDK LightModule.init 是异步注册，组件挂载时 ctx 可能尚未就绪）
const stopCtxWatch = watch(
  () => getCtx(),
  (ctx) => {
    if (ctx) refreshEnvSnapshots();
  },
  { immediate: false },
);

onMounted(() => {
  refreshEnvSnapshots();
  refreshTimer = setInterval(() => {
    // 只做低成本快照刷新（对齐 DebugPanel 每 1s updateStats）：
    // lightMesh 组变化 + 剔除诊断读数（activeSplats 由 SDK 侧每帧 update 写入，这里只读）。
    refreshMeshSnapshot();
    refreshCullSnapshot();
  }, 1000);
});

onUnmounted(() => {
  stopCtxWatch();
  window.removeEventListener('pointerdown', onDepthProbePointerDown, true);
  if (refreshTimer) {
    clearInterval(refreshTimer);
    refreshTimer = null;
  }
  disposeLightMarkers();
});

