function onRequestDepthProbe() {
  if (!postProcessingAvailable.value || depthProbePending.value) return;
  depthProbeArmed.value = true;
  window.addEventListener('pointerdown', onDepthProbePointerDown, true);
}

function onDepthProbePointerDown(event: PointerEvent) {
  const canvas = resolveViewerCanvas();
  if (!canvas) {
    depthProbeArmed.value = false;
    depthProbeError.value = '未找到渲染画布，无法定位采样像素';
    window.removeEventListener('pointerdown', onDepthProbePointerDown, true);
    return;
  }

  const rect = canvas.getBoundingClientRect();
  const insideCanvas = event.clientX >= rect.left && event.clientX <= rect.right &&
    event.clientY >= rect.top && event.clientY <= rect.bottom;
  if (!insideCanvas) return;

  event.preventDefault();
  event.stopPropagation();
  depthProbeArmed.value = false;
  window.removeEventListener('pointerdown', onDepthProbePointerDown, true);

  const u = (event.clientX - rect.left) / rect.width;
  const v = 1 - ((event.clientY - rect.top) / rect.height);
  void requestDepthProbe(u, v).then((snapshot) => {
    if (snapshot) console.info('[DepthProbe] 同像素三阶段深度', snapshot);
  });
}

function resolveViewerCanvas(): HTMLCanvasElement | null {
  return document.querySelector<HTMLCanvasElement>('canvas');
}

function formatDepthProbeNumber(value: number | null | undefined): string {
  return value === null || value === undefined ? '-' : value.toFixed(7);
}

function formatDepthProbeSample(label: string, sample: DepthProbeSample): string {
  const raw = sample.rawRgba ? `[${sample.rawRgba.join(', ')}]` : '-';
  return `${label}: ${sample.status}; z=${formatDepthProbeNumber(sample.perspectiveDepth)}; ` +
    `distance=${formatDepthProbeNumber(sample.viewDistance)}; encoded=${formatDepthProbeNumber(sample.encodedDepth)}; ` +
    `coverage=${formatDepthProbeNumber(sample.coverage)}; raw=${raw}`;
}

/**
 * 调用 LightModule 挂到 globalThis 的调试入口，打印当前场景全部光源 + IBL 强度。
 * 参考 light-module.ts v1.23.0：globalThis.__dumpLights = () => logSceneLights(...)。
 */
function onDumpLights() {
  const fn = (globalThis as unknown as { __dumpLights?: () => void }).__dumpLights;
  if (typeof fn === 'function') {
    fn();
  } else {
    // eslint-disable-next-line no-console
    console.warn('⚠️ __dumpLights() 未注册（LightModule 未 init 完成或已 dispose）');
  }
}

