/**
 * 反查当前 skyParams 匹配的预设名，用于初始加载时决定 skyPreset 下拉的初值。
 * 与 DebugPanel 原实现一致（浮点误差容忍 0.5%）。
 */
function detectSkyPreset(): string {
  for (const [presetName, preset] of Object.entries(skyPresets)) {
    const near = (a: number, b: number, epsRel = 0.005) =>
      Math.abs(a - b) <= Math.max(Math.abs(a), Math.abs(b), 1) * epsRel;
    if (
      near(skyParams.turbidity, preset.turbidity) &&
      near(skyParams.rayleigh, preset.rayleigh) &&
      near(skyParams.mieCoefficient, preset.mieCoefficient) &&
      near(skyParams.mieDirectionalG, preset.mieDirectionalG) &&
      near(skyParams.elevation, preset.elevation) &&
      near(skyParams.azimuth, preset.azimuth)
    ) {
      return presetName;
    }
  }
  return 'custom';
}

function onSkyPresetChange() {
  if (skyPreset.value === 'custom') return;
  const preset = skyPresets[skyPreset.value];
  if (!preset) return;
  todLockForManualEdit();
  skyParams.turbidity = preset.turbidity;
  skyParams.rayleigh = preset.rayleigh;
  skyParams.mieCoefficient = preset.mieCoefficient;
  skyParams.mieDirectionalG = preset.mieDirectionalG;
  skyParams.elevation = preset.elevation;
  skyParams.azimuth = preset.azimuth;
  applySkyAll();
}

