@author DannyCheung
-->
<template>
  <div class="performance-panel">
    <div class="performance-header">
      <h3>📊 性能统计</h3>
      <button class="close-btn" title="关闭性能统计面板" @click="onClose">×</button>
    </div>

    <div class="performance-content">
      <section class="performance-subpanel summary-subpanel">
        <h4>📈 性能统计</h4>
        <div class="performance-summary">
          <div class="summary-item">
            <span>FPS</span>
            <strong :class="getFpsClass(performanceStats.fps)">{{ performanceStats.fps }}</strong>
          </div>
          <div class="summary-item">
            <span>帧时间</span>
            <strong>{{ performanceStats.frameTime.toFixed(2) }} ms</strong>
          </div>
          <div class="summary-item">
            <span>内存</span>
            <strong>{{ performanceStats.memoryUsage.toFixed(1) }} MB</strong>
          </div>
        </div>
      </section>

      <!-- 内存统计：把摘要里的「内存 212.5 MB」拆成三组，用于判断占用来自 V8 堆（大数组 / 泄漏）
           还是 GPU 侧（贴图、几何体、后处理 RT）。 -->
      <section class="performance-subpanel memory-subpanel">
        <h4>🧠 内存统计</h4>
        <div class="memory-groups">
          <div class="memory-group">
            <div class="memory-group-title">JS 堆（V8）</div>
            <template v-if="jsHeap">
              <div class="memory-row"><span>已用</span><b>{{ formatMemoryBytes(jsHeap.usedBytes) }}</b></div>
              <div class="memory-row"><span>已分配</span><b>{{ formatMemoryBytes(jsHeap.totalBytes) }}</b></div>
              <div class="memory-row"><span>堆上限</span><b>{{ formatMemoryBytes(jsHeap.limitBytes) }}</b></div>
              <div class="memory-row"><span>占上限</span><b>{{ jsHeapUsageText }}</b></div>
            </template>
            <div v-else class="empty-state">当前浏览器未提供 performance.memory（Chromium 系可用）。</div>
          </div>

          <div class="memory-group">
            <div class="memory-group-title">渲染资源（renderer.info）</div>
            <template v-if="memorySnapshot">
              <div class="memory-row"><span>纹理数量</span><b>{{ memorySnapshot.resources.textures }}</b></div>
              <div class="memory-row"><span>几何体数量</span><b>{{ memorySnapshot.resources.geometries }}</b></div>
              <div class="memory-row"><span>着色器程序</span><b>{{ memorySnapshot.resources.programs }}</b></div>
            </template>
            <div v-else class="empty-state">RendererModule 未就绪。</div>
          </div>

          <div class="memory-group">
            <div class="memory-group-title">显存估算</div>
            <template v-if="memorySnapshot">
              <div class="memory-row"><span>场景纹理</span><b>{{ formatMemoryBytes(memorySnapshot.scene.estimatedTextureBytes) }}</b></div>
              <div class="memory-row"><span>场景几何体</span><b>{{ formatMemoryBytes(memorySnapshot.scene.estimatedGeometryBytes) }}</b></div>
              <div class="memory-row">
                <span>渲染链 RT<small v-if="!renderChainTextureReadout.sampled">开启「渲染耗时统计」采样后统计</small></span>
                <b>{{ renderChainTextureReadout.text }}</b>
              </div>
              <div class="memory-row">
                <span>场景对象</span>
                <b>{{ memorySnapshot.scene.renderableCount }} / {{ memorySnapshot.scene.objectCount }}<small>渲染对象 / 总数</small></b>
              </div>
              <div v-if="memorySnapshot.scene.unestimatedTextureCount > 0" class="memory-note">
                {{ memorySnapshot.scene.unestimatedTextureCount }} 张纹理格式未知，未计入估算
              </div>
            </template>
            <div v-else class="empty-state">等待渲染模块就绪…</div>
          </div>

          <div class="memory-group">
            <div class="memory-group-title">高斯地块</div>
            <template v-if="gaussianMemory && gaussianMemory.totalModules > 0">
              <div class="memory-row">
                <span>已加载地块</span>
                <b>{{ gaussianMemory.loadedModules }} / {{ gaussianMemory.totalModules }}</b>
              </div>
              <div v-if="gaussianMemory.pager" class="memory-row">
                <span>共享页面池<small>{{ formatSplatCount(gaussianMemory.pager.pageSplats) }} 椭球 / 页</small></span>
                <b
                  >{{ gaussianMemory.pager.usedPages }} / {{ gaussianMemory.pager.maxPages }} 页<small
                    >容量 {{ formatMemoryBytes(gaussianMemory.pager.poolBytes) }}</small
                  ></b
                >
              </div>

              <!-- 明细只列已加载地块（未加载地块不占显存）；paged 路径显示 RAD 分块进度与页面占用 -->
              <div v-if="loadedGaussianModules.length" class="gaussian-list">
                <div v-for="entry in loadedGaussianModules" :key="entry.moduleId" class="gaussian-item">
                  <div class="gaussian-item-head">
                    <span class="gaussian-name" :title="entry.moduleId">{{ entry.moduleName }}</span>
                    <b>{{ formatSplatCount(entry.totalSplats) }} 椭球</b>
                  </div>
                  <div class="gaussian-item-meta">
                    <span>{{ formatMemoryBytes(entry.estimatedBytes) }}</span>
                    <span v-if="entry.totalChunks !== null">{{ entry.loadedChunks ?? 0 }} / {{ entry.totalChunks }} 分块</span>
                    <span v-if="entry.pagerPages !== null">{{ entry.pagerPages }} 页</span>
                  </div>
                </div>
              </div>
              <div v-else class="empty-state">暂无已加载地块。</div>
              <div v-if="loadedGaussianModules.length" class="memory-note">显存按 32 B/椭球估算（不含 SH 高阶项与 ext 纹理）</div>
            </template>
            <div v-else class="empty-state">无地块配置（未加载高斯 / 策略未就绪）。</div>
          </div>
        </div>
      </section>

      <!-- 引擎侧：一帧 update 的 1 层调用（各模块耗时分布） -->
      <section class="performance-subpanel engine-stage-subpanel">
        <h4>⏱ 阶段耗时统计</h4>
        <div class="render-stage-profiler">
          <div v-if="!engineStageProfilerAvailable" class="subpanel-warning">
            {{ engineStageProfilerError || 'EngineRegistrar 未实现阶段耗时接口。' }}
          </div>
          <label class="debug-checkbox" :class="{ 'subpanel-disabled': !engineStageProfilerAvailable }">
            <input
              :checked="engineStageProfilerEnabled"
              :disabled="!engineStageProfilerAvailable"
              type="checkbox"
              @change="onEngineStageProfilerToggle"
            />
            <span>启用采样（每帧逐模块计时）</span>
          </label>

          <template v-if="engineStageProfilerSnapshot">
            <div class="render-context-grid">
              <span>采样窗口</span><b>{{ engineStageProfilerSnapshot.sampleWindow }} 帧</b>
              <span>已采样帧</span><b>{{ engineStageProfilerSnapshot.frame }}</b>
              <span>模块数</span><b>{{ engineStageProfilerSnapshot.stages.length }}</b>
            </div>

            <!-- 帧级拆分：帧间隔 = 帧内 CPU 忙 + 等待。先看这张表判断帧时间花在「忙」还是「等」，
                 再决定要不要往下抠模块耗时（与模块表同一 120 帧窗口，同步采样）。 -->
            <div class="render-stage-table-wrap">
              <table class="render-stage-table frame-timing-table">
                <thead>
                  <tr>
                    <th>帧级拆分</th>
                    <th>耗时<small>最新 / 均值 / P95</small></th>
                    <th>占帧间隔<small>均值占比</small></th>
                  </tr>
                </thead>
                <tbody>
                  <tr v-for="row in frameTimingRows" :key="row.label">
                    <td><span>{{ row.label }}</span><small>{{ row.hint }}</small></td>
                    <td>{{ formatTiming(row.timing) }}</td>
                    <td>{{ row.share }}</td>
                  </tr>
                </tbody>
              </table>
            </div>
            <div v-if="frameTimingVerdict" class="render-texture-summary">帧间隔构成（均值）：{{ frameTimingVerdict }}</div>

            <div class="render-stage-table-wrap">
              <table class="render-stage-table engine-stage-table">
                <thead>
                  <tr>
                    <th>模块</th>
                    <th>Phase / Priority</th>
                    <th>耗时<small>最新 / 均值 / P95</small></th>
                    <th>占比<small>均值占比</small></th>
                  </tr>
                </thead>
                <tbody>
                  <tr v-for="stage in engineStageProfilerSnapshot.stages" :key="stage.name">
                    <td><span>{{ stage.name }}</span></td>
                    <td>{{ formatSchedulePhase(stage.phase) }} · {{ stage.priority }}</td>
                    <td>{{ formatTiming(stage) }}</td>
                    <td>{{ formatStageShare(stage.averageMs) }}</td>
                  </tr>
                </tbody>
                <tfoot v-if="engineStageTotals">
                  <tr class="stage-total-row">
                    <td>模块合计</td>
                    <td>-</td>
                    <td>{{ formatTotal(engineStageTotals.sum, engineStageTotals.count) }}</td>
                    <td>100.0%</td>
                  </tr>
                </tfoot>
              </table>
            </div>
          </template>
          <div v-else-if="engineStageProfilerEnabled" class="empty-state">等待首帧统计…</div>
          <div v-else class="empty-state">启用采样后显示一帧内各模块 update 的耗时分布（1 层调用）。</div>
        </div>
      </section>

      <section class="performance-subpanel render-stage-subpanel">
        <h4>⏱ 渲染耗时统计</h4>
        <div class="render-stage-profiler">
          <div v-if="!renderStageProfilerAvailable" class="subpanel-warning">RendererModule 未就绪，无法启用阶段耗时统计。</div>
          <label class="debug-checkbox" :class="{ 'subpanel-disabled': !renderStageProfilerAvailable }">
            <input :checked="renderStageProfilerEnabled" :disabled="!renderStageProfilerAvailable" type="checkbox" @change="onRenderStageProfilerToggle" />
            <span>启用采样（会增加渲染诊断开销）</span>
          </label>
          <div v-if="renderStageProfilerError" class="subpanel-warning">{{ renderStageProfilerError }}</div>

          <template v-if="renderStageProfilerSnapshot">
            <div class="render-context-grid">
              <span>窗口</span><b>{{ formatResolution(renderStageProfilerSnapshot.context.windowSize) }}</b>
              <span>renderSize</span><b>{{ formatResolution(renderStageProfilerSnapshot.context.renderSize) }}</b>
              <span>drawingBuffer</span><b>{{ formatResolution(renderStageProfilerSnapshot.context.drawingBufferSize) }}</b>
              <span>scale / DPR</span><b>{{ formatScale(renderStageProfilerSnapshot.context.renderScale) }} / {{ formatScale(renderStageProfilerSnapshot.context.pixelRatio) }}</b>
              <span>提交路径</span><b>{{ renderStageProfilerSnapshot.context.submissionPath }}</b>
              <span>GPU Timer</span><b>{{ renderStageProfilerSnapshot.context.gpuTimerStatus }}</b>
              <template v-if="hybridRuntimeSnapshot">
                <span>Hybrid 基础目标</span><b>{{ formatResolution(hybridRuntimeSnapshot.baseSize) }}</b>
                <span>Mesh 实际目标</span><b>{{ formatResolution(hybridRuntimeSnapshot.meshSize) }}</b>
                <span>请求 / 实际倍率</span>
                <b :class="{ 'hybrid-downgraded': hybridRuntimeSnapshot.downgraded }">
                  {{ formatScale(hybridRuntimeSnapshot.requestedScale) }}× / {{ formatScale(hybridRuntimeSnapshot.effectiveScale) }}×
                </b>
                <span>Mesh 像素 / 预算</span>
                <b>{{ formatPixelCount(hybridRuntimeSnapshot.meshSize.width * hybridRuntimeSnapshot.meshSize.height) }} / {{ formatPixelCount(hybridRuntimeSnapshot.maxMeshPixels) }}</b>
              </template>
            </div>

            <div class="render-stage-table-wrap">
              <table class="render-stage-table">
                <thead>
                  <tr>
                    <th>Pass / Effect</th>
                    <th>状态</th>
                    <th>CPU<small>最新 / 均值 / P95</small></th>
                    <th>GPU<small>最新 / 均值 / P95</small></th>
                    <th>Draw</th>
                  </tr>
                </thead>
                <tbody>
                  <tr v-for="stage in renderStageProfilerSnapshot.stages" :key="stage.id" :class="{ 'is-effect': stage.kind === 'effect' }">
                    <td><span>{{ stage.label }}</span><small v-if="stage.inactiveReason">{{ stage.inactiveReason }}</small></td>
                    <td><span class="stage-status" :class="stageStatusClass(stage)">{{ stageStatusText(stage) }}</span></td>
                    <td>{{ stage.kind === 'effect' ? '融合' : formatTiming(stage.cpu) }}</td>
                    <td>{{ stage.kind === 'effect' ? '归属主 Pass' : formatTiming(stage.gpu) }}</td>
                    <td>{{ formatDraw(stage.draw) }}</td>
                  </tr>
                </tbody>
                <tfoot v-if="stageTotals">
                  <tr class="stage-total-row">
                    <td>顶层 Pass 合计</td>
                    <td>-</td>
                    <td>{{ formatTotal(stageTotals.cpu, stageTotals.cpuSamples) }}</td>
                    <td>{{ formatTotal(stageTotals.gpu, stageTotals.gpuSamples) }}</td>
                    <td>-</td>
                  </tr>
                </tfoot>
              </table>
            </div>

            <div class="render-texture-summary">纹理估算总计：{{ formatBytes(renderStageProfilerSnapshot.totalEstimatedTextureBytes) }}（共享纹理已去重）</div>
            <button class="debug-button render-stage-export" @click="onExportRenderStageProfilerSnapshot">导出 JSON 快照</button>

            <div class="render-stage-table-wrap">
              <table class="render-stage-table resource-table">
                <thead>
                  <tr><th>纹理资源</th><th>尺寸 / 格式</th><th>估算显存</th></tr>
                </thead>
                <tbody>
                  <tr v-for="texture in renderStageProfilerSnapshot.textures" :key="texture.id">
                    <td><span>{{ texture.label }}</span><small>{{ texture.producerIds.join(', ') }} → {{ texture.consumerIds.join(', ') || '无采样消费方' }}</small></td>
                    <td>{{ formatTextureInfo(texture) }}</td>
                    <td>{{ formatBytes(texture.estimatedBytes) }} · {{ texture.estimateStatus }}</td>
                  </tr>
                </tbody>
              </table>
            </div>
          </template>
          <div v-else-if="renderStageProfilerEnabled" class="empty-state">等待首帧统计快照…</div>
          <div v-else class="empty-state">启用采样后显示各渲染阶段、Draw 与纹理资源统计。</div>
        </div>
      </section>
    </div>
  </div>
</template>

<script setup lang="ts">
/**
 * @changelog
 *   v1.0.0 - 新增性能统计面板与阶段耗时统计迁移入口。
 *            REQ: 20260803-depth-pipeline-phase4 TECH: performance-panel-layout
 *   v1.1.0 - 迁入 DebugPanel 的 FPS、帧时间和内存轻量性能摘要。
 *            REQ: 20260803-depth-pipeline-phase4 TECH: performance-panel-summary-migration
 *   v1.2.0 - 由父级条件挂载，避免隐藏面板参与异步更新。
 *            BUGFIX: performance-panel-vue-update
 *   v1.3.0 - 显示 Hybrid 请求/实际倍率、目标尺寸、像素预算与颜色取证阶段。
 *            BUGFIX: hybrid-edge-diagnostics
 *   v1.4.0 - 白边根因确认后移除临时的颜色取证阶段展示，保留请求/实际倍率与像素预算诊断。
 *            BUGFIX: hybrid-edge-diagnostics
 * /@changelog
 *
 * @author DannyCheung
 */
import { computed, onMounted, onUnmounted, reactive, ref, shallowRef, watch } from 'vue';
import {
  debugModule,
  getModule,
  gs3dModule,
  rendererModule,
  SchedulePhase,
  type GaussianSplatMemorySnapshot,
  type Gs3dModuleState,
  type PerformanceStats,
  type RendererMemorySnapshot,
} from '@tencent/viewer-sdk';
import { useEngineContextGetter } from '../composables/useEngineContext';
import { useRenderStageProfiler } from '../composables/useRenderStageProfiler';
import { useEngineStageProfiler } from '../composables/useEngineStageProfiler';

/** performance.memory 读数（字节）。Chromium 系专有，Safari / Firefox 不提供。 */
interface JsHeapSnapshot {
  usedBytes: number;
  totalBytes: number;
  limitBytes: number;
}

const emit = defineEmits<{ close: [] }>();
const getCtx = useEngineContextGetter();
const performanceStats = reactive<PerformanceStats>({ fps: 0, frameTime: 0, physicsTime: 0, renderTime: 0, memoryUsage: 0 });

/**
 * 内存统计读数：
 * - JS 堆走浏览器 performance.memory（同步、零成本）；
 * - 渲染资源走 rendererModule.getMemorySnapshot（内部遍历场景换算字节，1s 轮询一次即可，
 *   不要放进每帧路径）。
 */
const jsHeap = ref<JsHeapSnapshot | null>(null);
const memorySnapshot = shallowRef<RendererMemorySnapshot | null>(null);
/** 高斯地块资源快照（地块椭球数 / RAD 分块进度 / 共享页面池分摊），与上面同频 1s 轮询。 */
const gaussianMemory = shallowRef<GaussianSplatMemorySnapshot | null>(null);
const {
  available: renderStageProfilerAvailable,
  enabled: renderStageProfilerEnabled,
  error: renderStageProfilerError,
  snapshot: renderStageProfilerSnapshot,
  hybridSnapshot: hybridRuntimeSnapshot,
  refresh: refreshRenderStageProfiler,
  setEnabled: setRenderStageProfilerEnabled,
} = useRenderStageProfiler(getCtx);

// 引擎侧：一帧 update 的 1 层调用（各模块耗时）
const {
  available: engineStageProfilerAvailable,
  enabled: engineStageProfilerEnabled,
  error: engineStageProfilerError,
  snapshot: engineStageProfilerSnapshot,
  refresh: refreshEngineStageProfiler,
  setEnabled: setEngineStageProfilerEnabled,
} = useEngineStageProfiler(getCtx);

/** 模块耗时合计（占比列的分母）。 */
const engineStageTotals = computed(() => {
  const snapshot = engineStageProfilerSnapshot.value;
  if (!snapshot) return null;
  let sum = 0;
  let count = 0;
  for (const stage of snapshot.stages) {
    if (stage.averageMs !== null) {
      sum += stage.averageMs;
      count += 1;
    }
  }
  return { sum, count };
});

/**
 * 帧级拆分三行：帧间隔 / 帧内 CPU（忙）/ 等待。
 *
 * 判读方式：帧内 CPU 远小于帧间隔 → 帧时间花在等待（VSync 对齐、浏览器渲染/合成、提交同步点）
 * 而不是 SDK 计算，此时抠模块耗时收益有限；反之才该顺着下面的模块表往下查。
 * 另外「帧内 CPU」应 ≥「模块合计」（后者只含模块 update，不含 onTick 回调等本层 JS），
 * 若明显小于模块合计，说明模块表有重复计入。
 */
const frameTimingRows = computed(() => {
  const timing = engineStageProfilerSnapshot.value?.frameTiming;
  if (!timing) return [];
  const intervalAverage = timing.interval.averageMs;
  const shareOf = (value: number | null): string =>
    value === null || intervalAverage === null || intervalAverage <= 0
      ? '-'
      : `${((value / intervalAverage) * 100).toFixed(1)}%`;
  return [
    { label: '帧间隔', hint: 'rAF→rAF，与「帧时间」同口径', timing: timing.interval, share: '100.0%' },
    {
      label: '帧内 CPU',
      hint: 'SDK 侧 JS：模块 update + onTick',
      timing: timing.cpuBusy,
      share: shareOf(timing.cpuBusy.averageMs),
    },
    { label: '等待', hint: '间隔 − CPU：VSync + 浏览器侧', timing: timing.idle, share: shareOf(timing.idle.averageMs) },
  ];
});

/** 帧间隔构成结论（均值口径）：一眼看出该往「计算量」还是「等待」方向优化。 */
const frameTimingVerdict = computed(() => {
  const timing = engineStageProfilerSnapshot.value?.frameTiming;
  const interval = timing?.interval.averageMs ?? null;
  const busy = timing?.cpuBusy.averageMs ?? null;
  if (!timing || interval === null || busy === null || interval <= 0) return null;
  const busyPct = Math.min(100, Math.max(0, (busy / interval) * 100));
  const idlePct = 100 - busyPct;
  const advice = idlePct >= 50 ? '瓶颈在等待，不在 SDK 计算' : 'CPU 忙时间占多数，瓶颈在计算';
  return `CPU 忙 ${busyPct.toFixed(1)}% · 等待 ${idlePct.toFixed(1)}% —— ${advice}`;
});

/**
 * 顶层 Pass 的 CPU / GPU 合计。
 *
 * 为什么只算 `parentId === null` 的 pass：HybridRenderPass 的子阶段（mesh-supersampled-render /
 * mesh-resolve / gaussian-base-render 等）是 render-pass **内部**的工作，其耗时已被父阶段的墙钟时间
 * 覆盖，一并求和会重复计入导致虚高。effect 类（融合进主 EffectPass）没有独立数值，同样跳过。
 *
 * GPU 合计是**近似值**：查询异步回读，各 Pass 的最近样本可能来自不同帧（且 `p95` 不可直接相加，
 * 这里统一用 average 求和），所以读数只用于判断量级与占比。
 */
const stageTotals = computed(() => {
  const snapshot = renderStageProfilerSnapshot.value;
  if (!snapshot) return null;
  let cpu = 0;
  let gpu = 0;
  let cpuSamples = 0;
  let gpuSamples = 0;
  for (const stage of snapshot.stages) {
    if (stage.kind !== 'pass' || stage.parentId !== null) continue;
    if (stage.cpu.averageMs !== null) {
      cpu += stage.cpu.averageMs;
      cpuSamples += 1;
    }
    if (stage.gpu.averageMs !== null) {
      gpu += stage.gpu.averageMs;
      gpuSamples += 1;
    }
  }
  return {
    cpu: cpuSamples > 0 ? cpu : null,
    gpu: gpuSamples > 0 ? gpu : null,
    cpuSamples,
    gpuSamples,
  };
});

/** JS 堆使用率（占堆上限百分比；读不到上限时给占位符）。 */
const jsHeapUsageText = computed(() => {
  const heap = jsHeap.value;
  if (!heap || heap.limitBytes <= 0) return '—';
  return `${((heap.usedBytes / heap.limitBytes) * 100).toFixed(1)}%`;
});

/**
 * 渲染链纹理显存读数（后处理 RT / 中间纹理，去重）。
 *
 * 三态区分（不能简单用 `?? null` 一律显示「未采样」）：
 * - 未开启采样：profiler 不持有资源列表 → `未采样`（显示 0 会被误读成「没有占用」）；
 * - 已采样但估算总计为 null：有纹理但存在无法确认格式的项 → `部分不可估`；
 * - 已采样：显示估算字节（无后处理的场景本帧无渲染链资源，显示 `0 B` 是正确结果）。
 */
const renderChainTextureReadout = computed<{ sampled: boolean; text: string }>(() => {
  const snapshot = renderStageProfilerSnapshot.value;
  if (!snapshot) return { sampled: false, text: '未采样' };
  const total = snapshot.totalEstimatedTextureBytes;
  if (total === null) return { sampled: true, text: '部分不可估' };
  return { sampled: true, text: formatMemoryBytes(total) };
});

/** 已加载的高斯地块（未加载地块不占显存，明细列表只列已加载项；计数仍用全量）。 */
const loadedGaussianModules = computed(() => gaussianMemory.value?.modules.filter((entry) => entry.loaded) ?? []);

function onClose(): void {
  emit('close');
}

function getFpsClass(fps: number): string {
  if (fps >= 50) return 'fps-good';
  if (fps >= 30) return 'fps-ok';
  return 'fps-bad';
}

function refreshPerformanceStats(): void {
  // v6.0.0：getPerformanceStats 改走 debugModule.api.getPerformanceStats(ctx) 形态（debugManager 已删除）。
  const ctx = getCtx();
  if (!ctx) return;
  const stats = getModule(ctx, debugModule).api.getPerformanceStats(ctx);
  if (stats) Object.assign(performanceStats, stats);
}

function refreshMemoryStats(): void {
  jsHeap.value = readJsHeapSnapshot();
  const ctx = getCtx();
  if (!ctx) {
    memorySnapshot.value = null;
    return;
  }
  try {
    memorySnapshot.value = rendererModule.getMemorySnapshot(ctx);
  } catch {
    // rendererModule 未就绪（launch 失败 / 已 dispose）时保持空态
    memorySnapshot.value = null;
  }
}

function refreshGaussianMemory(): void {
  const ctx = getCtx();
  if (!ctx) {
    gaussianMemory.value = null;
    return;
  }
  try {
    // strategies 是 gs3dModule 的公开字段（调试/诊断用途）；策略未创建时返回 null → 面板空态
    gaussianMemory.value = getModule<Gs3dModuleState>(ctx, gs3dModule).strategies?.getSplatMemoryStats() ?? null;
  } catch {
    gaussianMemory.value = null;
  }
}

/** 读 performance.memory（Chromium 专有；字段缺失视为不可用）。 */
function readJsHeapSnapshot(): JsHeapSnapshot | null {
  const {memory} = (performance as unknown as {
    memory?: { usedJSHeapSize?: number; totalJSHeapSize?: number; jsHeapSizeLimit?: number };
  });
  if (!memory || typeof memory.usedJSHeapSize !== 'number') return null;
  return {
    usedBytes: memory.usedJSHeapSize,
    totalBytes: memory.totalJSHeapSize ?? 0,
    limitBytes: memory.jsHeapSizeLimit ?? 0,
  };
}

function onRenderStageProfilerToggle(event: Event): void {
  const enabled = (event.target as HTMLInputElement).checked;
  setRenderStageProfilerEnabled(enabled);
  if (enabled) refreshRenderStageProfiler();
}

function onEngineStageProfilerToggle(event: Event): void {
  const enabled = (event.target as HTMLInputElement).checked;
  setEngineStageProfilerEnabled(enabled);
  if (enabled) refreshEngineStageProfiler();
}

function onExportRenderStageProfilerSnapshot(): void {
  const snapshot = renderStageProfilerSnapshot.value;
  if (!snapshot) return;
  const content = JSON.stringify({ exportedAt: new Date().toISOString(), ...snapshot }, null, 2);
  const url = URL.createObjectURL(new Blob([content], { type: 'application/json' }));
  const link = document.createElement('a');
  link.href = url;
  link.download = `render-stage-profiler-${Date.now()}.json`;
  link.click();
  window.setTimeout(() => URL.revokeObjectURL(url), 0);
}

function formatResolution(size: { width: number; height: number } | null): string {
  return size ? `${size.width} × ${size.height}` : '-';
}

function formatScale(value: number | null): string {
  return value === null ? '-' : value.toFixed(2);
}

function formatPixelCount(value: number): string {
  return value.toLocaleString('en-US');
}

function formatTiming(timing: { latestMs: number | null; averageMs: number | null; p95Ms: number | null }): string {
  if (timing.latestMs === null) return '-';
  return `${timing.latestMs.toFixed(2)} / ${timing.averageMs?.toFixed(2) ?? '-'} / ${timing.p95Ms?.toFixed(2) ?? '-'} ms`;
}

/** 合计行文案：附样本项数，便于判断该合计覆盖了几个 Pass（GPU 样本异步回读，项数可能暂时少于 CPU）。 */
function formatTotal(value: number | null, sampleCount: number): string {
  if (value === null) return '-';
  return `${value.toFixed(2)} ms（${sampleCount} 项）`;
}

/** 调度阶段枚举 → 可读名；未声明 phase 的模块由 phaseOf(priority) 推导，标注为「推导」。 */
function formatSchedulePhase(phase: number | null): string {
  if (phase === null) return '（推导）';
  return SchedulePhase[phase] ?? String(phase);
}

/** 模块耗时占「模块合计」的比例 —— 比占整帧时间更稳（不受 VSync 等待与未计入部分干扰）。 */
function formatStageShare(averageMs: number | null): string {
  const total = engineStageTotals.value?.sum ?? 0;
  if (averageMs === null || total <= 0) return '-';
  return `${((averageMs / total) * 100).toFixed(1)}%`;
}

function formatDraw(draw: { calls: number | null; triangles: number | null; points: number | null; status: string } | null): string {
  if (!draw) return '-';
  const { calls } = draw;
  if (calls === null) return '-';
  let prefix = '';
  if (draw.status === 'partial') prefix = 'partial · ';
  else if (draw.status === 'unavailable') prefix = 'unavailable · ';
  return `${prefix}${calls} calls · ${draw.triangles ?? 0} tri · ${draw.points ?? 0} pts`;
}

function formatBytes(bytes: number | null): string {
  if (bytes === null) return 'partial / unavailable';
  if (bytes < 1024) return `${bytes} B`;
  if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KiB`;
  return `${(bytes / (1024 * 1024)).toFixed(2)} MiB`;
}

/** 椭球数缩写：1234567 → 1.23 M（面板列宽有限，不显示完整位数）。 */
function formatSplatCount(count: number | null): string {
  if (count === null) return '—';
  if (count >= 1e6) return `${(count / 1e6).toFixed(2)} M`;
  if (count >= 1e3) return `${(count / 1e3).toFixed(1)} K`;
  return String(count);
}

/** 内存统计读数格式化：多一档 GiB（V8 堆上限常为 2~4 GiB，按 MiB 显示会到四位数）。 */
function formatMemoryBytes(bytes: number | null): string {
  if (bytes === null) return '—';
  if (bytes < 1024) return `${bytes} B`;
  if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KiB`;
  if (bytes < 1024 * 1024 * 1024) return `${(bytes / (1024 * 1024)).toFixed(2)} MiB`;
  return `${(bytes / (1024 * 1024 * 1024)).toFixed(2)} GiB`;
}

function formatTextureInfo(texture: { width: number | null; height: number | null; format: string | null; type: string | null; samples: number | null }): string {
  const size = texture.width && texture.height ? `${texture.width} × ${texture.height}` : '-';
  const format = [texture.format, texture.type].filter(Boolean).join(' / ') || '-';
  // samples 是「每像素采样数」而不是「N× MSAA」：1 表示**未启用**多重采样，
  // 早期版本直接拼成 `1× MSAA` 会让人误以为 MSAA 开着（实测被问到过）。只在 >1 时标注 MSAA。
  const samples = texture.samples ?? null;
  let sampling = '';
  if (samples !== null && samples > 1) sampling = ` · ${samples}× MSAA`;
  else if (samples !== null) sampling = ' · 无 MSAA';
  return `${size} · ${format}${sampling}`;
}

function stageStatusText(stage: { availability: string; executedThisFrame: boolean }): string {
  if (stage.availability === 'unavailable') return '不可用';
  if (stage.executedThisFrame) return '运行';
  return '未激活';
}

function stageStatusClass(stage: { availability: string; executedThisFrame: boolean }): string {
  if (stage.availability === 'unavailable') return 'is-unavailable';
  return stage.executedThisFrame ? 'is-active' : 'is-inactive';
}

const stopCtxWatch = watch(
  () => getCtx(),
  (ctx) => {
    if (ctx) {
      refreshPerformanceStats();
      refreshMemoryStats();
      refreshGaussianMemory();
      refreshRenderStageProfiler();
      refreshEngineStageProfiler();
    }
  },
);
let refreshTimer: ReturnType<typeof setInterval> | null = null;

onMounted(() => {
  refreshPerformanceStats();
  refreshMemoryStats();
  refreshGaussianMemory();
  refreshRenderStageProfiler();
  refreshEngineStageProfiler();
  refreshTimer = setInterval(() => {
    refreshPerformanceStats();
    refreshMemoryStats();
    refreshGaussianMemory();
    if (renderStageProfilerEnabled.value) refreshRenderStageProfiler();
    if (engineStageProfilerEnabled.value) refreshEngineStageProfiler();
  }, 1000);
});

onUnmounted(() => {
  stopCtxWatch();
  if (refreshTimer) clearInterval(refreshTimer);
});
</script>

