import { reactive, ref } from 'vue';
import type {
  CullSnapshot,
  DepthProbeSnapshot,
  EngineContext,
  OcclusionCullPresetId,
  PmndrsToneMappingMode,
  SmaaQuality,
  SplatDepthPresetName,
} from '@tencent/viewer-sdk';
import { DEFAULT_CULL_CONFIG, DEFAULT_SPLAT_DEPTH_PRESET, postProcessingModule } from '@tencent/viewer-sdk';

type DepthDebugSource = 'none' | 'preDepth' | 'renderPassDepth' | 'hybridPassDepth';
type DepthDebugMode = 'pip' | 'fullscreen';

/** 后处理面板响应式参数（与 DebugPanel 控件双向绑定） */
export interface PostProcessingPanelParams {
  antialiasing: { enabled: boolean; preset: SmaaQuality };
  bloom: {
    enabled: boolean;
    intensity: number;
    luminanceThreshold: number;
    luminanceSmoothing: number;
    radius: number;
    levels: number;
    resolutionScale: number;
  };
  ssao: { enabled: boolean; intensity: number; radius: number; resolutionScale: number };
  screenSpaceShadow: {
    enabled: boolean;
    quality: 'performance' | 'high';
    opacity: number;
    coverageThreshold: number;
    edgeThreshold: number;
    filterRadius: number;
    bias: number;
    applyToMesh: boolean;
  };
  pmndrsToneMapping: { enabled: boolean; mode: PmndrsToneMappingMode; exposure: number };
  /** 深度检查器：PreDepth、普通 RenderPass 或 HybridPass 合成主深度，均支持 PIP/全屏。 */
  depthDebug: { source: DepthDebugSource; mode: DepthDebugMode };
  /** 在 RenderPass 前注入有 coverage 的 Gaussian PreDepth 主深度 */
  routePreDepthToRenderPass: boolean;
  /**
   * 高斯深度与剔除（spark2.0 官方能力）：
   * 深度 pass 档位、深度剔除（OcclusionCull）、深度/彩色两个 pass 各自的相机剔除与静止保护。
   */
  cull: {
    /** 深度 pass 档位（低 / 中 / 高）。 */
    splatDepthPreset: SplatDepthPresetName;
    /** 深度剔除开关（按深度图剔除被遮挡高斯）。 */
    occlusionEnabled: boolean;
    /** 深度剔除档位（保守 / 均衡 / 激进）。 */
    occlusionPreset: OcclusionCullPresetId;
    /** 深度 pass 相机剔除（只切 behind 判据）。 */
    depthViewCullEnabled: boolean;
    /** 深度 pass 静止保护。 */
    depthViewCullSettle: boolean;
    /** 彩色 pass（高斯 RGB 渲染）相机剔除。 */
    colorViewCullEnabled: boolean;
    /** 彩色 pass 静止保护。 */
    colorViewCullSettle: boolean;
  };
}

/**
 * usePostProcessingParams — 后处理面板状态 + 命令式 action 封装
 *
 * 设计要点（对齐 useHdriParams）：
 * - `getCtx()` 工厂返回 `EngineContext | undefined`：sceneManager 可能尚未初始化
 * - 所有 action 内置 try/catch 探测 postProcessingModule 是否注册（配置缺失即未注册）
 * - 走 `@change/@input` 命令式回调，不做 watch 自动同步，避免双向同步隐式行为
 * - `refreshFromConfig` 读取模块当前配置快照写入 reactive params；时机由 DebugPanel 决定
 */
export function usePostProcessingParams(getCtx: () => EngineContext | undefined) {
  /** 后处理是否可用（已注册且 composer 存在） */
  const available = ref(false);
  /** 当前主渲染 pass 是否为 Mesh/Gaussian 分域合成的 HybridPass。 */
  const hybridPassActive = ref(false);
  /** 同像素三阶段深度探针的最后一次结果；仅由用户显式采样更新。 */
  const depthProbe = ref<DepthProbeSnapshot | null>(null);
  const depthProbePending = ref(false);
  const depthProbeError = ref<string | null>(null);
  /**
   * 剔除诊断快照（`null` = 剔除链路未就绪：SplatDepthPass 或主 SparkRenderer 尚未创建）。
   * 由 `refreshCullSnapshot` 按轮询刷新，用于展示 activeSplats 等运行时读数。
   */
  const cullSnapshot = ref<CullSnapshot | null>(null);

  /** 面板参数 */
  const params = reactive<PostProcessingPanelParams>({
    antialiasing: { enabled: true, preset: 'high' },
    bloom: {
      enabled: true,
      intensity: 1.0,
      luminanceThreshold: 0.95,
      luminanceSmoothing: 0.06,
      radius: 0.85,
      levels: 8,
      resolutionScale: 0.5,
    },
    ssao: { enabled: true, intensity: 1.0, radius: 0.1825, resolutionScale: 0.5 },
    screenSpaceShadow: {
      enabled: false,
      quality: 'high',
      opacity: 0.35,
      coverageThreshold: 0.05,
      edgeThreshold: 0.02,
      filterRadius: 1,
      bias: -0.0005,
      applyToMesh: false,
    },
    pmndrsToneMapping: { enabled: true, mode: 'ACESFilmic', exposure: 1.0 },
    depthDebug: { source: 'none', mode: 'fullscreen' },
    routePreDepthToRenderPass: false,
    // 缺省值与 SDK 侧 DEFAULT_CULL_CONFIG / DEFAULT_SPLAT_DEPTH_PRESET 对齐（两处 SSoT 必须一致：
    // 面板显示开、运行时没开是最难查的一类问题）。
    cull: {
      splatDepthPreset: DEFAULT_SPLAT_DEPTH_PRESET,
      occlusionEnabled: DEFAULT_CULL_CONFIG.occlusionEnabled,
      occlusionPreset: DEFAULT_CULL_CONFIG.occlusionPreset,
      depthViewCullEnabled: DEFAULT_CULL_CONFIG.depthViewCullEnabled,
      depthViewCullSettle: DEFAULT_CULL_CONFIG.depthViewCullSettle,
      colorViewCullEnabled: DEFAULT_CULL_CONFIG.colorViewCullEnabled,
      colorViewCullSettle: DEFAULT_CULL_CONFIG.colorViewCullSettle,
    },
  });

  /**
   * 从 postProcessingModule 当前配置快照同步面板参数与可用状态。
   * 未注册（无 renderer.postProcessing 配置）时静默返回 false。
   */
  function refreshFromConfig(): boolean {
    const ctx = getCtx();
    if (!ctx) return false;

    let snapshot;
    try {
      snapshot = postProcessingModule.getConfigSnapshot(ctx);
    } catch {
      available.value = false;
      return false;
    }

    if (!snapshot) {
      available.value = false;
      return false;
    }

    available.value = postProcessingModule.hasComposer(ctx);
    hybridPassActive.value = postProcessingModule.isHybridRenderPass(ctx);

    params.antialiasing.enabled = snapshot.antialiasing.enabled;
    params.antialiasing.preset = snapshot.antialiasing.preset;
    params.bloom.enabled = snapshot.bloom.enabled;
    params.bloom.intensity = snapshot.bloom.intensity;
    params.bloom.luminanceThreshold = snapshot.bloom.luminanceThreshold;
    params.bloom.luminanceSmoothing = snapshot.bloom.luminanceSmoothing;
    params.bloom.radius = snapshot.bloom.radius;
    params.bloom.levels = snapshot.bloom.levels;
    params.bloom.resolutionScale = snapshot.bloom.resolutionScale;
    params.ssao.enabled = snapshot.ssao.enabled;
    params.ssao.intensity = snapshot.ssao.intensity;
    params.ssao.radius = snapshot.ssao.radius;
    params.ssao.resolutionScale = snapshot.ssao.resolutionScale;
    params.pmndrsToneMapping.enabled = snapshot.pmndrsToneMapping.enabled;
    params.pmndrsToneMapping.mode = snapshot.pmndrsToneMapping.mode;
    params.pmndrsToneMapping.exposure = snapshot.pmndrsToneMapping.exposure;

    const screenSpaceShadow = postProcessingModule.getScreenSpaceShadowConfig(ctx);
    if (screenSpaceShadow) Object.assign(params.screenSpaceShadow, screenSpaceShadow);

    const depthDebug = postProcessingModule.getDepthDebugSelection(ctx);
    if (depthDebug) params.depthDebug = depthDebug;
    params.routePreDepthToRenderPass = postProcessingModule.getRoutePreDepthToRenderPass(ctx);

    // 剔除与深度档位：链路尚未就绪（SplatDepthPass 未创建）时返回 null，
    // 此时保留面板当前值 —— 初值已与 SDK 缺省对齐，不会出现「面板显示开、实际没开」。
    const cull = postProcessingModule.getCullSnapshot(ctx);
    cullSnapshot.value = cull;
    if (cull) {
      params.cull.splatDepthPreset = cull.depthPass.preset;
      params.cull.occlusionEnabled = cull.occlusion.enabled;
      params.cull.occlusionPreset = cull.occlusion.preset;
      params.cull.depthViewCullEnabled = cull.depthPass.depthCullEnabled;
      params.cull.depthViewCullSettle = cull.depthPass.depthCullSettle;
      params.cull.colorViewCullEnabled = cull.colorViewCull.enabled;
      params.cull.colorViewCullSettle = cull.colorViewCull.settle;
    }

    return available.value;
  }

  /**
   * 只刷新剔除诊断快照（读数行专用）：按 1s 级轮询调用，避免整表 `refreshFromConfig` 的开销。
   * 链路未就绪（深度 pass 尚未创建）时写 `null`，读数行据此呈现提示而不是留旧值。
   */
  function refreshCullSnapshot(): void {
    const ctx = getCtx();
    if (!ctx) {
      cullSnapshot.value = null;
      return;
    }
    try {
      cullSnapshot.value = postProcessingModule.getCullSnapshot(ctx);
    } catch {
      cullSnapshot.value = null;
    }
  }

  // ======================== 命令式 setter（@change / @input 回调） ========================

  function setEffectEnabled(effect: 'antialiasing' | 'bloom' | 'ssao' | 'pmndrsToneMapping', enabled: boolean): void {
    const ctx = getCtx();
    if (!ctx) return;
    try {
      postProcessingModule.setEffectEnabled(ctx, effect, enabled);
    } catch {
      /* 未注册，忽略 */
    }
  }

  function applyBloomIntensity(): void {
    const ctx = getCtx();
    if (!ctx) return;
    try {
      postProcessingModule.setBloomIntensity(ctx, params.bloom.intensity);
    } catch {
      /* 未注册，忽略 */
    }
  }

  function applyBloomThreshold(): void {
    const ctx = getCtx();
    if (!ctx) return;
    try {
      postProcessingModule.setBloomThreshold(ctx, params.bloom.luminanceThreshold);
    } catch {
      /* 未注册，忽略 */
    }
  }

  function applyBloomRadius(): void {
    const ctx = getCtx();
    if (!ctx) return;
    try {
      postProcessingModule.setBloomRadius(ctx, params.bloom.radius);
    } catch {
      /* 未注册，忽略 */
    }
  }

  function applyBloomSmoothing(): void {
    const ctx = getCtx();
    if (!ctx) return;
    try {
      postProcessingModule.setBloomSmoothing(ctx, params.bloom.luminanceSmoothing);
    } catch {
      /* 未注册，忽略 */
    }
  }

  function applyBloomLevels(): void {
    const ctx = getCtx();
    if (!ctx) return;
    try {
      postProcessingModule.setBloomLevels(ctx, params.bloom.levels);
    } catch {
      /* 未注册，忽略 */
    }
  }

  function applyBloomResolutionScale(): void {
    const ctx = getCtx();
    if (!ctx) return;
    try {
      postProcessingModule.setBloomResolutionScale(ctx, params.bloom.resolutionScale);
    } catch {
      /* 未注册，忽略 */
    }
  }

  function applySsaoIntensity(): void {
    const ctx = getCtx();
    if (!ctx) return;
    try {
      postProcessingModule.setSsaoIntensity(ctx, params.ssao.intensity);
    } catch {
      /* 未注册，忽略 */
    }
  }

  function applySsaoRadius(): void {
    const ctx = getCtx();
    if (!ctx) return;
    try {
      postProcessingModule.setSsaoRadius(ctx, params.ssao.radius);
    } catch {
      /* 未注册，忽略 */
    }
  }

  function applySsaoResolutionScale(): void {
    const ctx = getCtx();
    if (!ctx) return;
    try {
      postProcessingModule.setSsaoResolutionScale(ctx, params.ssao.resolutionScale);
    } catch {
      /* 未注册，忽略 */
    }
  }

  function applyScreenSpaceShadow(): void {
    const ctx = getCtx();
    if (!ctx) return;
    try {
      postProcessingModule.setScreenSpaceShadowConfig(ctx, { ...params.screenSpaceShadow });
    } catch (error) {
      console.warn('[usePostProcessingParams] 屏幕空间阴影参数更新失败', error);
    }
  }

  function applyToneMappingMode(): void {
    const ctx = getCtx();
    if (!ctx) return;
    try {
      postProcessingModule.setToneMappingMode(ctx, params.pmndrsToneMapping.mode);
    } catch {
      /* 未注册，忽略 */
    }
  }

  function applyToneMappingExposure(): void {
    const ctx = getCtx();
    if (!ctx) return;
    try {
      postProcessingModule.setToneMappingExposure(ctx, params.pmndrsToneMapping.exposure);
    } catch {
      /* 未注册，忽略 */
    }
  }

  function applyAntialiasingPreset(): void {
    const ctx = getCtx();
    if (!ctx) return;
    try {
      postProcessingModule.setAntialiasingPreset(ctx, params.antialiasing.preset);
    } catch {
      /* 未注册，忽略 */
    }
  }

  function applyDepthDebug(): void {
    const ctx = getCtx();
    if (!ctx) return;
    try {
      postProcessingModule.setDepthDebug(ctx, params.depthDebug.source, params.depthDebug.mode);
    } catch (error) {
      console.warn('[usePostProcessingParams] 深度检查器切换失败', error);
    }
  }

  function applyRoutePreDepthToRenderPass(): void {
    const ctx = getCtx();
    if (!ctx) return;
    try {
      postProcessingModule.setRoutePreDepthToRenderPass(ctx, params.routePreDepthToRenderPass);
    } catch (error) {
      console.warn('[usePostProcessingParams] PreDepth 注入切换失败', error);
    }
  }

  /** 深度 pass 档位（低 / 中 / 高）。 */
  function applySplatDepthPreset(): void {
    const ctx = getCtx();
    if (!ctx) return;
    try {
      postProcessingModule.setSplatDepthPreset(ctx, params.cull.splatDepthPreset);
    } catch (error) {
      console.warn('[usePostProcessingParams] 深度档位切换失败', error);
    }
  }

  /**
   * 深度剔除开关 + 档位（判据与 σ 门槛由档位统一决定）。
   *
   * 两条调用各自 try/catch：任何一条失败都不应阻断另一条 —— 曾踩过「setEnabled 抛错 →
   * 同一个 catch 吞掉 → setPreset 永远执行不到」的自锁（表现为档位读数恒为旧值）。
   */
  function applyOcclusionCull(): void {
    const ctx = getCtx();
    if (!ctx) return;
    try {
      postProcessingModule.setOcclusionCullEnabled(ctx, params.cull.occlusionEnabled);
    } catch (error) {
      console.warn('[usePostProcessingParams] 深度剔除开关更新失败', error);
    }
    try {
      postProcessingModule.setOcclusionCullPreset(ctx, params.cull.occlusionPreset);
    } catch (error) {
      console.warn('[usePostProcessingParams] 深度剔除档位更新失败', error);
    }
  }

  /** 深度 pass 相机剔除 + 静止保护。 */
  function applyDepthViewCull(): void {
    const ctx = getCtx();
    if (!ctx) return;
    try {
      postProcessingModule.setDepthViewCull(ctx, {
        enabled: params.cull.depthViewCullEnabled,
        settle: params.cull.depthViewCullSettle,
      });
    } catch (error) {
      console.warn('[usePostProcessingParams] 深度 pass 相机剔除参数更新失败', error);
    }
  }

  /** 彩色 pass（高斯 RGB 渲染）相机剔除 + 静止保护。 */
  function applyColorViewCull(): void {
    const ctx = getCtx();
    if (!ctx) return;
    try {
      postProcessingModule.setColorViewCull(ctx, {
        enabled: params.cull.colorViewCullEnabled,
        settle: params.cull.colorViewCullSettle,
      });
    } catch (error) {
      console.warn('[usePostProcessingParams] 彩色 pass 相机剔除参数更新失败', error);
    }
  }

  /** 请求下一帧同一 WebGL UV 的 Splat / 注入后 / RenderPass stable 三阶段深度。 */
  async function requestDepthProbe(u: number, v: number): Promise<DepthProbeSnapshot | null> {
    const ctx = getCtx();
    if (!ctx) {
      depthProbeError.value = 'EngineContext 未就绪';
      return null;
    }

    depthProbePending.value = true;
    depthProbeError.value = null;
    try {
      const snapshot = await postProcessingModule.requestDepthProbe(ctx, { u, v });
      depthProbe.value = snapshot;
      return snapshot;
    } catch (error) {
      const message = error instanceof Error ? error.message : String(error);
      depthProbeError.value = message;
      console.warn('[usePostProcessingParams] 同像素深度探针失败', error);
      return null;
    } finally {
      depthProbePending.value = false;
    }
  }

  return {
    // state
    available,
    hybridPassActive,
    params,
    depthProbe,
    depthProbePending,
    depthProbeError,
    cullSnapshot,
    // actions
    refreshFromConfig,
    refreshCullSnapshot,
    setEffectEnabled,
    applyBloomIntensity,
    applyBloomThreshold,
    applyBloomSmoothing,
    applyBloomRadius,
    applyBloomLevels,
    applyBloomResolutionScale,
    applySsaoIntensity,
    applySsaoRadius,
    applySsaoResolutionScale,
    applyScreenSpaceShadow,
    applyToneMappingMode,
    applyToneMappingExposure,
    applyAntialiasingPreset,
    applyDepthDebug,
    applyRoutePreDepthToRenderPass,
    applySplatDepthPreset,
    applyOcclusionCull,
    applyDepthViewCull,
    applyColorViewCull,
    requestDepthProbe,
  };
}
