import { inject, markRaw, provide, toRaw, type InjectionKey, type Ref } from 'vue';
import type { EngineContext } from '@tencent/viewer-sdk';

/**
 * EngineContext 的注入 key。
 * 值为 Ref<EngineContext | undefined>：viewerSDK 异步初始化后再赋值，初始为 undefined。
 */
export const EngineContextKey: InjectionKey<Ref<EngineContext | undefined>> = Symbol('EngineContext');

/**
 * 在父组件（SceneViewer.vue）setup 顶层调用，向后代提供 EngineContext Ref。
 *
 * 用法：
 * ```ts
 * const engineCtxRef = ref<EngineContext | undefined>(undefined);
 * provideEngineContext(engineCtxRef);
 * onMounted(async () => {
 *   await viewerSDK.init(...);
 *   engineCtxRef.value = viewerSDK.getContext() ?? undefined;
 * });
 * ```
 */
export function provideEngineContext(ctxRef: Ref<EngineContext | undefined>): void {
  // EngineContext 持有 renderer/scene/camera/Object3D/Map 等外部可变对象，禁止 Vue 深层响应式代理。
  if (ctxRef.value) ctxRef.value = markRaw(toRaw(ctxRef.value));
  provide(EngineContextKey, ctxRef);
}

/**
 * 在子组件 setup 顶层调用，inject EngineContext Ref。
 * 找不到 provider 时抛错（对齐 thirdroom useMainThreadContext 的硬守卫语义）。
 *
 * 注意：返回的是 Ref 而非 EngineContext 本身，使用时需 .value 拆包；
 * 多数场景下应改用 useEngineContextGetter() 获得 () => ctx 闭包。
 */
export function useEngineContext(): Ref<EngineContext | undefined> {
  const ctxRef = inject(EngineContextKey);
  if (!ctxRef) {
    throw new Error(
      '[useEngineContext] EngineContext has not been provided. Make sure an ancestor component calls provideEngineContext(ctxRef) in its setup.',
    );
  }
  return ctxRef;
}

/**
 * 返回一个无参 getter：调用时返回当前最新的 EngineContext（可能为 undefined，因为
 * viewerSDK 异步初始化未完成时 ctx 还不存在）。
 *
 * 适用于命令式调用场景（事件回调、watch 回调内向 viewer-sdk 模块 API 透传 ctx）。
 *
 * 用法：
 * ```ts
 * const getCtx = useEngineContextGetter();
 * const { hdriParams } = useHdriParams(getCtx);
 * ```
 */
export function useEngineContextGetter(): () => EngineContext | undefined {
  const ctxRef = useEngineContext();
  return () => {
    const ctx = ctxRef.value;
    return ctx ? markRaw(toRaw(ctx)) : undefined;
  };
}
