import { ref, shallowRef } from 'vue';
import {
  postProcessingModule,
  rendererModule,
  type EngineContext,
  type HybridResolutionRuntimeSnapshot,
  type RenderStageProfilerSnapshot,
} from '@tencent/viewer-sdk';

/** 环境面板使用的阶段耗时诊断桥接；不把 Three.js 对象放入 Vue 响应式状态。 */
export function useRenderStageProfiler(getCtx: () => EngineContext | undefined) {
  const available = ref(false);
  const enabled = ref(false);
  const error = ref<string | null>(null);
  const snapshot = shallowRef<RenderStageProfilerSnapshot | null>(null);
  const hybridSnapshot = shallowRef<HybridResolutionRuntimeSnapshot | null>(null);

  /** 仅在 Profiler 已开启时拉取快照，供面板的低频定时器调用。 */
  function refresh(): boolean {
    const ctx = getCtx();
    if (!ctx) {
      available.value = false;
      enabled.value = false;
      snapshot.value = null;
      hybridSnapshot.value = null;
      return false;
    }
    try {
      available.value = true;
      enabled.value = rendererModule.isRenderStageProfilerEnabled(ctx);
      snapshot.value = enabled.value ? rendererModule.getRenderStageProfilerSnapshot(ctx) : null;
      hybridSnapshot.value = postProcessingModule.getHybridResolutionRuntimeSnapshot(ctx);
      error.value = null;
      return enabled.value;
    } catch (reason) {
      available.value = false;
      enabled.value = false;
      snapshot.value = null;
      hybridSnapshot.value = null;
      error.value = reason instanceof Error ? reason.message : String(reason);
      return false;
    }
  }

  /** 启用或关闭 SDK 侧采样；关闭后立即丢弃 UI 快照，避免无意义轮询。 */
  function setEnabled(nextEnabled: boolean): void {
    const ctx = getCtx();
    if (!ctx) {
      error.value = 'EngineContext 未就绪';
      return;
    }
    try {
      rendererModule.setRenderStageProfilerEnabled(ctx, nextEnabled);
      enabled.value = nextEnabled;
      available.value = true;
      snapshot.value = nextEnabled ? rendererModule.getRenderStageProfilerSnapshot(ctx) : null;
      hybridSnapshot.value = postProcessingModule.getHybridResolutionRuntimeSnapshot(ctx);
      error.value = null;
    } catch (reason) {
      enabled.value = false;
      snapshot.value = null;
      error.value = reason instanceof Error ? reason.message : String(reason);
    }
  }

  return { available, enabled, error, snapshot, hybridSnapshot, refresh, setEnabled };
}
