<script setup lang="ts">
/**
 * @changelog
 *   v1.0.0 - 从 DebugPanel / DebugScenePanel 迁移可视化、高斯显隐与区域模块调试能力。
 *            REQ: debugpanel-拆分-阶段2 TECH: scene-panel-debug-subpanel
 *   v1.1.0 - 新增「地块调试」分组（showGaussianBounds / showCollisionChunkBounds / showTerrainChunkBounds / showNpcChunkBounds），
 *            「显示高度图分块边界」从 🎨 可视化分组迁入并改名「显示地形分块边界」，
 *            「显示高斯泼溅边界」从 🎨 可视化分组迁入。
 *            REQ: 1070211994137074908 地块调试分组
 *   v1.2.0 - 「🟩 地块调试」分组新增「显示 Light 分块边界」。
 *            REQ: 1070211994137074908 light-chunk 可视化
 *   v1.3.0 - 移除「💡 光照分块方案」只读数据卡（方案 A）与「显示 Light 光照方案（3D 指示器）」开关（方案 C）。
 *            REQ: 1070211994137074908 light-chunk 可视化收敛
 *   v1.4.0 - 「🎨 可视化」分组新增「显示点光源位置」开关。
 *            REQ: 20260831-pointlight-visualization
 *   v1.5.0 - 「🎨 可视化」分组新增「显示 Light Probe 体积盒」开关。
 *            REQ: 20260831-lightprobe-visualization
 * /@changelog
 *
 * @author DannyCheung
 */
import { computed, nextTick, onMounted, onUnmounted, reactive, ref, watch } from 'vue';
import type { DebugConfig } from '@tencent/viewer-sdk';
// v2.0.0（sceneManager/debugManager prop 死代码整体清理）：debugManager.config 改走
// ctx-based helper（getDebugConfig），未就绪时返回安全默认值。
// v6.0.0：getDebugConfig 改走 debugModule.api.xxx(ctx, ...) 形态
// v1.13.0：环境光只读色块（S9）读取 ambientModule.getAmbientSnapshot
import { debugModule, getModule, ambientModule } from '@tencent/viewer-sdk';
import { useGaussianVisibility } from '../composables/useGaussianVisibility';
import { useEngineContextGetter } from '../composables/useEngineContext';

interface RegionModuleInfo {
  id: string;
  name: string;
}

interface Props {
  initialConfig?: Partial<DebugConfig>;
}

const props = defineProps<Props>();
const emit = defineEmits<{
  configChange: [config: DebugConfig];
  moduleToggle: [moduleName: string, shouldLoad: boolean];
}>();

const getCtx = useEngineContextGetter();
const {
  visible: gaussianVisible,
  refresh: refreshGaussianVisibility,
  toggle: toggleGaussianVisibility,
} = useGaussianVisibility(getCtx);

const debugConfig = reactive<DebugConfig>({
  showColliders: false,
  showColliderSolid: false,
  showCharacterController: false,
  showPerformanceStats: true,
  showPhysicsInfo: true,
  wireframeMode: false,
  showTerrain: false,
  showTriggerZones: false,
  showCliffDetection: false,
  showGaussianBounds: false,
  showSpringArmEdgeDetection: false,
  showTerrainChunkBounds: false,
  showCollisionChunkBounds: false,
  showNpcChunkBounds: false,
  showLightChunkBounds: false,
  showProgramChunkBounds: false,
  showPointLights: false,
  showLightProbeVolume: false,
  showDirectionalLights: false,
  showHdriProbe: false,
  showSkySun: false,
  showLightCullingRange: false,
});

// v1.13.0（S9）：环境光只读色块数据源（每轮询周期刷新）
const ambientSnapshot = ref<{ color: number; intensity: number }>({ color: 0xffffff, intensity: 1 });
const ambientCssColor = computed(
  () => `#${ambientSnapshot.value.color.toString(16).padStart(6, '0')}`,
);

const regionModules = ref<RegionModuleInfo[]>([]);
const loadedModules = reactive(new Set<string>());
const loadingModules = reactive(new Set<string>());
const dropdownOpen = ref(false);
const searchKeyword = ref('');
const dropdownRef = ref<HTMLElement | null>(null);
const searchInputRef = ref<HTMLInputElement | null>(null);
let updateTimer: ReturnType<typeof setInterval> | null = null;

const filteredModules = computed(() => {
  const keyword = searchKeyword.value.trim().toLowerCase();
  return keyword
    ? regionModules.value.filter((module) => module.name.toLowerCase().includes(keyword))
    : regionModules.value;
});

watch(
  () => props.initialConfig,
  (config) => {
    if (!config) return;
    Object.assign(debugConfig, config);
    emitConfigChange();
  },
  { immediate: true },
);

function emitConfigChange(): void {
  emit('configChange', { ...debugConfig });
}

function onColliderVisualToggle(field: 'showColliders' | 'showColliderSolid'): void {
  const other = field === 'showColliders' ? 'showColliderSolid' : 'showColliders';
  if (debugConfig[field]) debugConfig[other] = false;
  emitConfigChange();
}

function applyConfig(partial: Partial<DebugConfig>): void {
  Object.assign(debugConfig, partial);
}

function toggleDropdown(): void {
  dropdownOpen.value = !dropdownOpen.value;
  if (!dropdownOpen.value) return;
  searchKeyword.value = '';
  void nextTick(() => searchInputRef.value?.focus());
}

function onSelectModule(module: RegionModuleInfo): void {
  if (loadingModules.has(module.name)) return;
  if (loadedModules.has(module.name)) {
    loadedModules.delete(module.name);
    emit('moduleToggle', module.name, false);
    return;
  }
  loadingModules.add(module.name);
  emit('moduleToggle', module.name, true);
}

function setRegionModules(modules: Array<{ id?: string; name: string }>): void {
  regionModules.value = modules.map((module) => ({ id: module.id ?? module.name, name: module.name }));
}

function onModuleLoaded(moduleName: string): void {
  loadingModules.delete(moduleName);
  loadedModules.add(moduleName);
}

function onModuleLoadFailed(moduleName: string): void {
  loadingModules.delete(moduleName);
}

function onModuleUnloaded(moduleName: string): void {
  loadedModules.delete(moduleName);
  loadingModules.delete(moduleName);
}

function getLoadingModules(): string[] {
  return [...loadingModules];
}

function refresh(): void {
  const ctx = getCtx();
  if (ctx) {
    const cfg = getModule(ctx, debugModule).api.getDebugConfig(ctx);
    if (cfg) Object.assign(debugConfig, cfg);
    // v1.13.0（S9）：环境光只读色块跟随实时状态（getAmbientSnapshot 未注册时返回安全默认）
    ambientSnapshot.value = ambientModule.getAmbientSnapshot(ctx);
  }
  refreshGaussianVisibility();
}

function onKeydown(event: KeyboardEvent): void {
  if (event.key === 'F2') {
    event.preventDefault();
    debugConfig.showColliders = !debugConfig.showColliders;
    onColliderVisualToggle('showColliders');
  }
  if (event.key === 'F3') {
    event.preventDefault();
    debugConfig.wireframeMode = !debugConfig.wireframeMode;
    emitConfigChange();
  }
}

onMounted(() => {
  refresh();
  updateTimer = setInterval(refresh, 1000);
  document.addEventListener('keydown', onKeydown);
});

onUnmounted(() => {
  if (updateTimer) clearInterval(updateTimer);
  document.removeEventListener('keydown', onKeydown);
});

defineExpose({
  applyConfig,
  getLoadingModules,
  onModuleLoaded,
  onModuleLoadFailed,
  onModuleUnloaded,
  setRegionModules,
});
</script>

